code:
@Operation(summary = "结构化 SSE 流式对话（支持重连）")
    @PostMapping(value = "/stream", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public SseEmitter chatStream(
            @RequestBody ChatStreamRequest request,
            @RequestHeader(value = "X-Workspace-Id", required = false) Long workspaceId,
            Authentication auth) {

        String conversationId = request.getConversationId() != null ? request.getConversationId() : "default";
        // SSE 超时设为 10 分钟，覆盖 servlet 默认的 30s，避免长回答被中断
        // RFC-058 PR-1: Utf8SseEmitter 显式声明 charset=UTF-8，防止中文在 Windows 中文 Chrome / 部分代理处乱码
        SseEmitter emitter = new Utf8SseEmitter(10 * 60 * 1000L);

        // Resolve the public base URL on THIS (request) thread. Every agent run
        // below is dispatched to sseExecutor / reactive callbacks that run off
        // the request thread, where the request is no longer bound and
        // ServletUriComponentsBuilder would yield null. Capturing it here lets
        // tool-generated download links carry an absolute host on the streaming,
        // approval-replay, and queued-message paths alike.
        final String requestBaseUrl = resolveRequestBaseUrl();

        // ---- 分支 A：断线重连 ----
        if (Boolean.TRUE.equals(request.getReconnect())) {
            String reconnectUser = auth != null ? auth.getName() : "anonymous";
            log.info("SSE reconnect: conversationId={}, user={}", conversationId, reconnectUser);

            // 校验会话归属
            if (!conversationService.isConversationOwner(conversationId, reconnectUser)) {
                try {
                    sendEvent(emitter, "error", Map.of("message", "无权访问该会话"));
                } catch (IOException e) {
                    log.warn("SSE reconnect auth error send failed: {}", e.getMessage());
                }
                emitter.complete();
                return emitter;
            }

            registerEmitterCallbacks(emitter, conversationId);

            // Issue #17 — distinguish "stream truly completed on this node"
            // from "stream is running on another node (multi-node deployment
            // without sticky session)". They look identical from attach()'s
            // boolean return, but the user-facing remediation is different.
            boolean existsLocally = streamTracker.streamExistsOnThisNode(conversationId);
            long lastEventId = request.getLastEventId() == null ? 0L : request.getLastEventId();
            boolean attached = streamTracker.attach(conversationId, emitter, lastEventId);
            if (!attached) {
                try {
                    if (existsLocally) {
                        // RunState exists here but is done — stream finished normally
                        sendEvent(emitter, "done", Map.of("status", "completed"));
                    } else {
                        // No RunState on this node. Either:
                        //  (a) The stream finished long ago and was cleaned up, OR
                        //  (b) Multi-node deployment routed this reconnect to a
                        //      DIFFERENT node than the originating one. The CE
                        //      build assumes single-instance (see ChatStreamTracker
                        //      class javadoc and rfc-054 §0); LB must be configured
                        //      for sticky session by conversationId.
                        // We can't tell (a) from (b) at this layer, so emit an
                        // explicit code the front-end can surface to operators.
                        log.info("SSE reconnect: no RunState locally for conversationId={} — " +
                                "either completed-and-cleaned or running on another node", conversationId);
                        sendEvent(emitter, "done", Map.of(
                                "status", "stream_not_local",
                                "message", "Stream is not active on this node. " +
                                        "If you're running a multi-node deployment, " +
                                        "verify the load balancer is configured for sticky " +
                                        "session by conversationId. See deploy/multi-node-deployment.md."
                        ));
                    }
                } catch (IOException e) {
                    log.warn("SSE reconnect done send error: {}", e.getMessage());
                }
                emitter.complete();
            }
            return emitter;
        }

        // ---- 分支 B：正常请求 ----
        Long agentId = request.getAgentId();
        String requestMessage = request.getMessage() != null ? request.getMessage() : "";
        if (auth == null) {
            try {
                sendEvent(emitter, "error", Map.of("message", "未登录，请先登录"));
            } catch (IOException e) {
                log.warn("SSE auth error send failed: {}", e.getMessage());
            }
            emitter.complete();
            return emitter;
        }
        String username = auth.getName();
        log.info("SSE chat: agentId={}, conversationId={}, user={}", agentId, conversationId, username);

        // ---- Workspace 边界校验：确保 agent 属于当前 workspace ----
        if (agentId != null) {
            AgentEntity agent = agentService.getAgent(agentId);
            if (agent != null && agent.getWorkspaceId() != null) {
                long wsId = workspaceId != null ? workspaceId : 1L;
                if (!agent.getWorkspaceId().equals(wsId)) {
                    log.warn("Chat workspace mismatch: agent {} belongs to workspace {}, request workspace {}",
                            agentId, agent.getWorkspaceId(), wsId);
                    try {
                        sendEvent(emitter, "error", Map.of("message", "Agent 不属于当前工作区"));
                        sendEvent(emitter, "done", Map.of("status", "completed"));
                    } catch (IOException e) {
                        log.warn("SSE workspace error send failed: {}", e.getMessage());
                    }
                    emitter.complete();
                    return emitter;
                }
            }
        }

        // Worker conversations are immutable evidence from the web UI. Keep this
        // guard at the user entry point so internal dispatch can still persist its
        // user/assistant execution transcript through ConversationService.
        if (!conversationService.isUserMessageAllowed(conversationId)) {
            sendErrorDoneAndComplete(emitter, "执行任务会话为只读，不能发送新消息");
            return emitter;
        }

        if (conversationService.conversationExists(conversationId)
                && !conversationService.isConversationOwner(conversationId, username)) {
            sendErrorDoneAndComplete(emitter, "无权操作该会话");
            return emitter;
        }

        // Reserve before approval consumption, regeneration or stream mutation.
        // Once registered, RunState protects the setup-to-subscription gap:
        // autonomous admission checks isRunning while holding this same gate.
        try (var setupPermit = turnGate.tryAcquire(conversationId)) {
        if (setupPermit == null || streamTracker.isRunning(conversationId)) {
            sendErrorDoneAndComplete(emitter, "正在生成回复，请先停止或排队后续消息");
            return emitter;
        }

        // ---- 审批命令拦截：/approve、/deny 走 SSE 流式 replay ----
        String normalizedMsg = requestMessage.trim().toLowerCase();
        boolean isApprovalCommand = "/approve".equals(normalizedMsg) || "approve".equals(normalizedMsg);
        boolean isDenyCommand = "/deny".equals(normalizedMsg) || "deny".equals(normalizedMsg);

        if (isApprovalCommand || isDenyCommand) {
            PendingApproval pending = findRequestedPendingApproval(
                    conversationId, request.getPendingApprovalId());
            if (pending == null) {
                try {
                    sendEvent(emitter, "error", Map.of("message", "当前没有待审批的工具调用"));
                    sendEvent(emitter, "done", Map.of("status", "completed"));
                } catch (IOException e) { /* ignore */ }
                emitter.complete();
                return emitter;
            }

            // deny: workflow.resolve handles DB + metadata + memory atomically.
            if (isDenyCommand) {
                ResolveOutcome denyOutcome;
                try {
                    denyOutcome = resolveWithCurrentApprover(pending, auth, username, false);
                } catch (vip.mate.exception.MateClawException revoked) {
                    sendErrorDoneAndComplete(emitter, revoked.getMessage());
                    return emitter;
                }
                conversationService.removeApprovalPlaceholders(conversationId);
                log.info("[Approval-Stream] User {} denied pending {} for conversation {} (dbSynced={}, msgRewritten={})",
                        username, pending.getPendingId(), conversationId,
                        denyOutcome.dbSynced(), denyOutcome.messagesRewritten());
            }

            // approve: atomic resolveAndConsume; workflow handles DB + metadata + memory.
            PendingApproval consumed = null;
            if (isApprovalCommand) {
                ResolveOutcome consumeOutcome;
                try {
                    consumeOutcome = resolveWithCurrentApprover(pending, auth, username, true);
                } catch (vip.mate.exception.MateClawException revoked) {
                    sendErrorDoneAndComplete(emitter, revoked.getMessage());
                    return emitter;
                }
                if (consumeOutcome.isAlreadyResolved()) {
                    try {
                        sendEvent(emitter, "error", Map.of("message", "审批记录已过期或已被处理"));
                        sendEvent(emitter, "done", Map.of("status", "completed"));
                    } catch (IOException e2) { /* ignore */ }
                    emitter.complete();
                    return emitter;
                }
                consumed = consumeOutcome.consumedSnapshot();
                // Clear residual approval placeholder messages so the LLM context for
                // replay doesn't include "[Awaiting approval]" text artifacts.
                conversationService.removeApprovalPlaceholders(conversationId);
                log.info("[Approval-Stream] User {} approved pending {} for conversation {} (msgRewritten={})",
                        username, consumed.getPendingId(), conversationId, consumeOutcome.messagesRewritten());
            }

            final PendingApproval finalConsumed = consumed;
            final String decision = isApprovalCommand ? "approved" : "denied";

            streamTracker.register(conversationId);
            setupPermit.close();
            Long approvalAgentId = parseLongOrNull(pending.getAgentId());
            streamTracker.bindRunMeta(conversationId, approvalAgentId, username);
            registerEmitterCallbacks(emitter, conversationId);
            streamTracker.attach(conversationId, emitter);
            AtomicBoolean approvalEmitterDone = new AtomicBoolean(false);

            sseExecutor.execute(() -> {
                AgentStreamAccumulator accumulator = newAccumulator();
                AtomicBoolean finalized = new AtomicBoolean(false);
                try {
                    // 广播 approval_resolved 事件
                    broadcastEvent(conversationId, "tool_approval_resolved", Map.of(
                            "pendingId", pending.getPendingId(),
                            "decision", decision,
                            "toolName", pending.getToolName(),
                            "timestamp", System.currentTimeMillis()
                    ));

                    if ("denied".equals(decision)) {
                        String denyMsg = "用户拒绝执行工具 " + pending.getToolName();
                        MessageEntity savedAssistant = conversationService.saveMessage(conversationId, "assistant", denyMsg);
                        broadcastEvent(conversationId, "message_start", Map.of("role", "assistant"));
                        broadcastEvent(conversationId, "content_delta", Map.of("delta", denyMsg));
                        broadcastEvent(conversationId, "message_complete", Map.of("status", "completed"));
                        broadcastEvent(conversationId, "done", buildDonePayload(
                                conversationId, "completed", savedAssistant, 0, 0,
                                isAssistantPersisted(savedAssistant),
                                conversationService.getMessageCount(conversationId)));
                        // deny 是正常 turn 终结，用户可能在 awaiting_approval 阶段排了消息
                        ChatStreamTracker.CompletionResult denyCr = streamTracker.completeAndConsumeIfLast(conversationId);
                        if (denyCr.allDone() && shouldDrainQueuedInput(conversationId, "completed")) {
                            startQueuedMessage(conversationId, emitter, approvalEmitterDone, username, requestBaseUrl);
                        } else {
                            completeEmitterQuietly(emitter, approvalEmitterDone);
                        }
                        return;
                    }

                    // approved: 使用已原子消费的记录触发 replay 流
                    if (finalConsumed == null) {
                        broadcastEvent(conversationId, "error", Map.of("message", "审批记录已被消费"));
                        broadcastEvent(conversationId, "done", Map.of("status", "completed"));
                        // 审批记录被另一个请求消费，但用户可能在等待期间排了消息
                        ChatStreamTracker.CompletionResult consumedNullCr = streamTracker.completeAndConsumeIfLast(conversationId);
                        if (consumedNullCr.allDone() && shouldDrainQueuedInput(conversationId, "completed")) {
                            startQueuedMessage(conversationId, emitter, approvalEmitterDone, username, requestBaseUrl);
                        } else {
                            completeEmitterQuietly(emitter, approvalEmitterDone);
                        }
                        return;
                    }

                    Long replayAgentId = finalConsumed.getAgentId() != null
                            ? Long.parseLong(finalConsumed.getAgentId()) : agentId;

                    broadcastEvent(conversationId, "message_start", Map.of("role", "assistant"));

                    // 不含工具名的中性 prompt（对齐 IM 渠道，防止 fallthrough 时误导 LLM）
                    String replayPrompt = "继续执行已批准的工具调用。";

                    streamTracker.incrementFlux(conversationId);
                    // RFC-063r §2.12: prefer the persisted Memento snapshot
                    // (covers cross-restart approval where the original channel
                    // is gone) and fall back to a fresh web-origin
                    // ChatOrigin when none was captured.
                    vip.mate.agent.context.ChatOrigin replayOrigin =
                            approvalService.restoreChatOrigin(finalConsumed.getChatOrigin());
                    if (replayOrigin == vip.mate.agent.context.ChatOrigin.EMPTY) {
                        replayOrigin = vip.mate.agent.context.ChatOrigin.web(
                                conversationId, username, workspaceId, null);
                    }
                    // Carry the request-thread base URL so any file a replayed
                    // tool generates gets an absolute download link.
                    replayOrigin = replayOrigin.withBaseUrl(requestBaseUrl).withApprovalId(finalConsumed.getPendingId());
                    Disposable disposable = agentService.chatWithReplayStream(
                            replayAgentId, replayPrompt, conversationId, finalConsumed.getToolCallPayload(), username, replayOrigin)
                            .doOnNext(delta -> {
                                if (approvalEmitterDone.get()) return;
                                try {
                                    accumulator.accept(delta, conversationId);
                                } catch (Exception e) {
                                    log.warn("SSE replay broadcast error: {}", e.getMessage());
                                }
                            })
                            .doOnComplete(() -> {
                                if (!finalized.compareAndSet(false, true)) return;
                                // Force-recycle short-circuit: see main doOnComplete below.
                                if (streamTracker.isRecycled(conversationId)) {
                                    log.info("SSE replay doOnComplete skipped for force-recycled conversation: {}", conversationId);
                                    try {
                                        conversationService.updateStreamStatus(conversationId, "idle");
                                    } catch (Exception e) {
                                        log.debug("recycled-skip: stream_status reset failed for {}: {}",
                                                conversationId, e.getMessage());
                                    }
                                    ChatStreamTracker.CompletionResult cr = streamTracker.completeAndConsumeIfLast(conversationId);
                                    if (cr.allDone()) {
                                        completeEmitterQuietly(emitter, approvalEmitterDone);
                                    }
                                    return;
                                }
                                // Replay can re-trigger an approval (the approved tool
                                // call may chain into another guarded tool). Derive status the same
                                // way as the normal stream so awaiting_approval doesn't get masked
                                // as completed.
                                boolean replayWasStopped = streamTracker.isStopRequested(conversationId);
                                ChatStreamTracker.InterruptType replayInterrupt = streamTracker.getInterruptType(conversationId);
                                boolean replayIsError = accumulator.getContent() != null
                                        && accumulator.getContent().startsWith("[错误] ");
                                String persistStatus = derivePersistStatus(
                                        accumulator.isAwaitingApproval(), replayIsError,
                                        replayWasStopped, replayInterrupt);
                                try {
                                    MessageEntity savedAssistant = null;
                                    List<MessageContentPart> parts = accumulator.toAssistantParts();
                                    String text = accumulator.getContent();
                                    if (!text.isBlank() || !parts.isEmpty()) {
                                        savedAssistant = conversationService.saveMessage(conversationId, "assistant", text, parts,
                                                persistStatus,
                                                accumulator.getPromptTokens(),
                                                accumulator.getCompletionTokens(),
                                                accumulator.getCacheReadTokens(),
                                                accumulator.getCacheWriteTokens(),
                                                accumulator.getReasoningTokens(),
                                                accumulator.getRuntimeModelName(),
                                                accumulator.getRuntimeProviderId(),
                                                accumulator.toMetadataJson());  // includes toolCalls metadata
                                    } else if (replayWasStopped) {
                                        boolean replayIsFollowup = replayInterrupt == ChatStreamTracker.InterruptType.USER_INTERRUPT_WITH_FOLLOWUP;
                                        savedAssistant = conversationService.saveMessage(conversationId, "assistant",
                                                replayIsFollowup ? "[已中断]" : "[已停止生成]", null, persistStatus);
                                    } else {
                                        savedAssistant = saveEmptyAssistantPlaceholder(
                                                conversationId, persistStatus, accumulator, "SSE replay doOnComplete");
                                    }
                                    broadcastEvent(conversationId, "message_complete", Map.of(
                                            "status", persistStatus,
                                            "hasThinking", !accumulator.getThinking().isBlank(),
                                            "hasContent", !text.isBlank()
                                    ));
                                    int msgCount = conversationService.getMessageCount(conversationId);
                                    broadcastEvent(conversationId, "done", buildDonePayload(
                                            conversationId, persistStatus, savedAssistant, 0, 0,
                                            isAssistantPersisted(savedAssistant), msgCount));
                                } catch (Exception e) {
                                    log.warn("SSE replay complete error: {}", e.getMessage());
                                } finally {
                                    ChatStreamTracker.CompletionResult cr = streamTracker.completeAndConsumeIfLast(conversationId);
                                    if (cr.allDone()) {
                                        if (shouldDrainQueuedInput(conversationId, persistStatus)) {
                                            startQueuedMessage(conversationId, emitter, approvalEmitterDone, username, requestBaseUrl);
                                        } else {
                                            conversationService.updateStreamStatus(conversationId, "idle");
                                            completeEmitterQuietly(emitter, approvalEmitterDone);
                                        }
                                    }
                                }
                            })
                            .doOnError(e -> {
                                if (!finalized.compareAndSet(false, true)) return;
                                // Force-recycle short-circuit: see main doOnComplete below.
                                if (streamTracker.isRecycled(conversationId)) {
                                    log.info("SSE replay doOnError skipped for force-recycled conversation: {}, cause={}",
                                            conversationId, e.getMessage());
                                    try {
                                        conversationService.updateStreamStatus(conversationId, "idle");
                                    } catch (Exception ex) {
                                        log.debug("recycled-skip: stream_status reset failed for {}: {}",
                                                conversationId, ex.getMessage());
                                    }
                                    ChatStreamTracker.CompletionResult cr = streamTracker.completeAndConsumeIfLast(conversationId);
                                    if (cr.allDone()) {
                                        completeEmitterQuietly(emitter, approvalEmitterDone);
                                    }
                                    return;
                                }

                                boolean isUserStop = e instanceof java.util.concurrent.CancellationException
                                        || (e.getCause() instanceof java.util.concurrent.CancellationException);
                                ChatStreamTracker.InterruptType replayInterruptType = streamTracker.getInterruptType(conversationId);
                                boolean replayIsFollowup = replayInterruptType == ChatStreamTracker.InterruptType.USER_INTERRUPT_WITH_FOLLOWUP;
                                String errStatus = !isUserStop ? "failed"
                                        : replayIsFollowup ? "interrupted" : "stopped";

                                if (replayIsFollowup) {
                                    log.info("SSE replay stream interrupted for follow-up: conversationId={}", conversationId);
                                } else if (isUserStop) {
                                    log.info("SSE replay stream stopped by user: conversationId={}", conversationId);
                                } else {
                                    log.error("SSE replay error: {}", e.getMessage());
                                }

                                try {
                                    MessageEntity savedAssistant = null;
                                    List<MessageContentPart> replayParts = accumulator.toAssistantParts();
                                    String replayText = accumulator.getContent();
                                    if (!replayText.isBlank() || !replayParts.isEmpty()) {
                                        String savedText = replayText.isBlank() && isUserStop
                                                ? (replayIsFollowup ? "[已中断]" : "[已停止生成]") : replayText;
                                        savedAssistant = conversationService.saveMessage(conversationId, "assistant", savedText, replayParts,
                                                errStatus,
                                                accumulator.getPromptTokens(),
                                                accumulator.getCompletionTokens(),
                                                accumulator.getCacheReadTokens(),
                                                accumulator.getCacheWriteTokens(),
                                                accumulator.getReasoningTokens(),
                                                accumulator.getRuntimeModelName(),
                                                accumulator.getRuntimeProviderId(),
                                                accumulator.toMetadataJson());
                                    } else if (isUserStop) {
                                        savedAssistant = conversationService.saveMessage(conversationId, "assistant",
                                                replayIsFollowup ? "[已中断]" : "[已停止生成]", null, errStatus);
                                    } else {
                                        savedAssistant = conversationService.saveMessage(conversationId, "assistant",
                                                "[错误] " + (e.getMessage() != null ? e.getMessage() : "replay error"),
                                                null, "failed");
                                    }

                                    if (replayIsFollowup) {
                                        broadcastEvent(conversationId, "message_complete", Map.of(
                                                "status", "interrupted",
                                                "hasThinking", !accumulator.getThinking().isBlank(),
                                                "hasContent", !replayText.isBlank()
                                        ));
                                        broadcastEvent(conversationId, "turn_interrupted", Map.of(
                                                "conversationId", conversationId,
                                                "hasQueuedMessage", streamTracker.hasQueuedMessage(conversationId)
                                        ));
                                    } else if (isUserStop) {
                                        broadcastEvent(conversationId, "message_complete", Map.of(
                                                "status", "stopped",
                                                "hasThinking", !accumulator.getThinking().isBlank(),
                                                "hasContent", !replayText.isBlank()
                                        ));
                                        int stoppedMsgCount = conversationService.getMessageCount(conversationId);
                                        broadcastEvent(conversationId, "done", buildDonePayload(
                                                conversationId, "stopped", savedAssistant, 0, 0,
                                                isAssistantPersisted(savedAssistant), stoppedMsgCount));
                                    } else {
                                        broadcastEvent(conversationId, "error", buildErrorPayload(
                                                conversationId,
                                                e.getMessage() != null ? e.getMessage() : "replay error",
                                                savedAssistant));
                                    }
                                } catch (Exception ex) {
                                    log.warn("SSE replay error finalize failed: {}", ex.getMessage());
                                }
                                streamTracker.clearInterruptState(conversationId);
                                ChatStreamTracker.CompletionResult cr = streamTracker.completeAndConsumeIfLast(conversationId);
                                if (cr.allDone()) {
                                    if (shouldDrainQueuedInput(conversationId, errStatus)) {
                                        startQueuedMessage(conversationId, emitter, approvalEmitterDone, username, requestBaseUrl);
                                    } else {
                                        conversationService.updateStreamStatus(conversationId, "idle");
                                        completeEmitterQuietly(emitter, approvalEmitterDone);
                                    }
                                }
                            })
                            .subscribe(
                                    chunk -> { },
                                    err -> log.debug("SSE replay subscription terminated: {}", err.getMessage()),
                                    () -> log.debug("SSE replay subscription completed: conversationId={}", conversationId));

                    streamTracker.setDisposable(conversationId, disposable);
                    streamTracker.setEmergencySaveCallback(conversationId,
                            () -> emergencySaveAccumulator(conversationId, accumulator));

                } catch (Exception e) {
                    log.error("SSE approval replay setup error: {}", e.getMessage());
                    streamTracker.complete(conversationId);
                    completeEmitterQuietly(emitter, approvalEmitterDone);
                }
            });
            return emitter;
        }

        // ---- 重新生成（regenerate=true）：删除会话末尾的 assistant 回答块，
        // 复用 DB 中的种子 user 消息作为本轮输入，不重复持久化 user 行。
        // message 字段被忽略，以持久化的种子为准。 ----
        final boolean regenerate = Boolean.TRUE.equals(request.getRegenerate());
        final ConversationService.RegenerateSeed regenerateSeed;
        if (regenerate) {
            if (!conversationService.isConversationOwner(conversationId, username)) {
                sendErrorDoneAndComplete(emitter, "无权操作该会话");
                return emitter;
            }
            if (streamTracker.isRunning(conversationId)) {
                sendErrorDoneAndComplete(emitter, "正在生成回复，请先停止再重新生成");
                return emitter;
            }
            regenerateSeed = conversationService.prepareRegenerate(conversationId);
            if (regenerateSeed == null) {
                sendErrorDoneAndComplete(emitter, "当前没有可重新生成的回答");
                return emitter;
            }
            log.info("SSE regenerate: conversationId={}, seedMessageId={}",
                    conversationId, regenerateSeed.seedMessageId());
        } else {
            regenerateSeed = null;
        }
        final String message = regenerateSeed != null
                ? (regenerateSeed.content() != null ? regenerateSeed.content() : "")
                : requestMessage;

        // Snapshot selection on the request thread before the executor can be
        // delayed behind other work. A Goal abandoned during model inference
        // must still be recognizable when that turn asks for approval.
        final vip.mate.agent.context.ChatOrigin selectedTurnOrigin;
        try {
            selectedTurnOrigin = captureWebGoal(memoryOrigin(conversationId, username,
                    requesterUserIdOf(auth), workspaceId, request.getEndUserId())
                    .withBaseUrl(requestBaseUrl), agentId);
        } catch (vip.mate.exception.MateClawException invalidSelection) {
            sendErrorDoneAndComplete(emitter, invalidSelection.getMessage());
            return emitter;
        }

        // ---- 正常请求：注册流状态并附着首个订阅者 ----
        streamTracker.register(conversationId);
        setupPermit.close();
        streamTracker.bindRunMeta(conversationId, agentId, username);
        registerEmitterCallbacks(emitter, conversationId);
        streamTracker.attach(conversationId, emitter);

        // Per-emitter "the SSE channel is open and you should reset any
        // pending placeholder UI". Sent directly to the emitter rather than
        // broadcast so reconnecting subscribers don't see a duplicate marker
        // for an already-open conversation.
        try {
            sendEvent(emitter, "stream_started", Map.of(
                    "conversationId", conversationId,
                    "timestamp", System.currentTimeMillis()
            ));
        } catch (IOException e) {
            log.debug("Failed to send stream_started event for {}: {}", conversationId, e.getMessage());
        }

        // 标记 emitter 是否已结束，防止 Flux 回调再次写入已关闭的 emitter
        AtomicBoolean emitterDone = new AtomicBoolean(false);

        sseExecutor.execute(() -> {
            AgentStreamAccumulator accumulator = newAccumulator();
            AtomicBoolean finalized = new AtomicBoolean(false);
            try {
                conversationService.getOrCreateConversation(conversationId, agentId, username, workspaceId);
                // Pin the model the user picked for this conversation so later
                // turns (and the runtime model resolver) honour it independently
                // of every other conversation.
                conversationService.updateConversationModel(conversationId,
                        request.getModelProvider(), request.getModelName());
                List<MessageContentPart> requestParts = regenerateSeed != null
                        ? regenerateSeed.parts()
                        : normalizeRequestParts(request);
                String promptText = buildPromptText(message, requestParts);
                Long originMessageId;
                if (regenerateSeed == null) {
                    // Regenerate reuses the already-persisted seed user row —
                    // inserting again would duplicate it (issue #547).
                    MessageEntity savedUser = conversationService
                            .saveMessage(conversationId, "user", message, requestParts);
                    originMessageId = savedUser == null ? null : savedUser.getId();
                } else {
                    originMessageId = regenerateSeed.seedMessageId();
                }
                conversationService.updateStreamStatus(conversationId, "running");

                broadcastEvent(conversationId, "session", Map.of(
                        "conversationId", conversationId,
                        "agentId", agentId
                ));
                broadcastEvent(conversationId, "message_start", Map.of(
                        "role", "assistant"
                ));

                streamTracker.incrementFlux(conversationId);
                // RFC-063r §2.5: web entry — null channelId / no ChannelTarget;
                // tools that need a workspace path read it from the agent (origin
                // is enriched with workspaceBasePath in StateGraph buildInitialState).
                vip.mate.agent.context.ChatOrigin webOrigin = selectedTurnOrigin.withOriginMessageId(originMessageId);
                Disposable disposable = agentService.chatStructuredStream(agentId, promptText, conversationId, username, request.getThinkingLevel(), webOrigin)
                        .doOnNext(delta -> {
                            if (emitterDone.get()) return;
                            try {
                                accumulator.accept(delta, conversationId);
                            } catch (Exception e) {
                                log.warn("SSE broadcast error: {}", e.getMessage());
                            }
                        })
                        .doOnComplete(() -> {
                            if (!finalized.compareAndSet(false, true)) return;
                            // Force-recycle: the recycle path already wrote a
                            // "[已被用户中止]" placeholder (or the partial
                            // content via emergencySave). The agent's flux may
                            // have completed the same millisecond — skip its
                            // save + broadcast so we don't append a duplicate
                            // assistant row below the placeholder. Cleanup
                            // still runs so queue draining + emitter close
                            // happen normally.
                            if (streamTracker.isRecycled(conversationId)) {
                                log.info("SSE doOnComplete skipped for force-recycled conversation: {}", conversationId);
                                streamTracker.clearInterruptState(conversationId);
                                // Defensive: keep DB stream_status consistent with the
                                // "this turn is over" reality even when we skip the
                                // save. Force-recycle's controller path already wrote
                                // 'idle' for the recycled run, so this is normally a
                                // no-op — but if a register() ever fails to clear the
                                // marker (e.g. a different turn snuck through), this
                                // prevents the row leaking at 'running' across refresh.
                                try {
                                    conversationService.updateStreamStatus(conversationId, "idle");
                                } catch (Exception e) {
                                    log.debug("recycled-skip: stream_status reset failed for {}: {}",
                                            conversationId, e.getMessage());
                                }
                                ChatStreamTracker.CompletionResult cr = streamTracker.completeAndConsumeIfLast(conversationId);
                                if (cr.allDone()) {
                                    completeEmitterQuietly(emitter, emitterDone);
                                }
                                return;
                            }
                            // 区分四种完成语义：
                            // 1. 正常完成（stopRequested=false）→ completed
                            // 2. 用户主动停止 → stopped
                            // 3. 用户中断后续跑（interrupt-with-followup）→ interrupted
                            // 4. LLM 客户端错误 / typed error → error
                            //    （NodeStreamingChatHelper 把 typed error 序列化为 "[错误] "
                            //     前缀的文本作为 content_delta 注入，accumulator 不区分，
                            //     这里靠前缀识别。打标 status='error' 后，BaseAgent
                            //     的 history sanitization 阶段会跳过这类消息，避免下次
                            //     prompt 被污染——DeepSeek thinking mode 缺
                            //     reasoning_content 立即 400，Claude 不接受 assistant
                            //     prefill 也 400，二者循环复制错误。）
                            boolean wasStopped = streamTracker.isStopRequested(conversationId);
                            ChatStreamTracker.InterruptType interruptType = streamTracker.getInterruptType(conversationId);
                            boolean isInterruptFollowup = interruptType == ChatStreamTracker.InterruptType.USER_INTERRUPT_WITH_FOLLOWUP;
                            boolean isError = accumulator.getContent() != null
                                    && accumulator.getContent().startsWith("[错误] ");
                            String persistStatus = derivePersistStatus(
                                    accumulator.isAwaitingApproval(), isError, wasStopped, interruptType);
                            try {
                                MessageEntity savedAssistant = null;
                                List<MessageContentPart> assistantParts = accumulator.toAssistantParts();
                                String assistantText = accumulator.getContent();
                                if (!assistantText.isBlank() || !assistantParts.isEmpty()) {
                                    String savedText = assistantText.isBlank() && wasStopped
                                            ? (isInterruptFollowup ? "[已中断]" : "[已停止生成]") : assistantText;
                                    savedAssistant = conversationService.saveMessage(conversationId, "assistant", savedText, assistantParts,
                                            persistStatus,
                                            accumulator.getPromptTokens(),
                                            accumulator.getCompletionTokens(),
                                            accumulator.getCacheReadTokens(),
                                            accumulator.getCacheWriteTokens(),
                                            accumulator.getReasoningTokens(),
                                            accumulator.getRuntimeModelName(),
                                            accumulator.getRuntimeProviderId(),
                                            accumulator.toMetadataJson());
                                } else if (wasStopped) {
                                    savedAssistant = conversationService.saveMessage(conversationId, "assistant",
                                            isInterruptFollowup ? "[已中断]" : "[已停止生成]", null, persistStatus);
                                } else {
                                    savedAssistant = saveEmptyAssistantPlaceholder(
                                            conversationId, persistStatus, accumulator, "SSE doOnComplete");
                                }
                                // 发布对话完成事件（仅正常完成时；停止/中断/错误均不触发记忆提取）
                                // RFC-049 follow-up: also skip on isError — error turns persist
                                // garbage like "[错误] Bad request..." as the assistant reply,
                                // which would pollute the memory extraction pipeline if propagated.
                                if (!wasStopped && !isError) {
                                    // Attribute the memory write to the same owner the read
                                    // path recalled this turn — the publish runs in a reactive
                                    // completion callback after the origin holder is cleared,
                                    // so resolve from the captured webOrigin explicitly.
                                    completionPublisher.publish(agentId, conversationId, message, assistantText, "web",
                                            memoryOwnerResolver.resolve(webOrigin));
                                }

                                if (isInterruptFollowup) {
                                    broadcastEvent(conversationId, "message_complete", Map.of(
                                            "status", "interrupted",
                                            "hasThinking", !accumulator.getThinking().isBlank(),
                                            "hasContent", !assistantText.isBlank()
                                    ));
                                    broadcastEvent(conversationId, "turn_interrupted", Map.of(
                                            "conversationId", conversationId,
                                            "hasQueuedMessage", streamTracker.hasQueuedMessage(conversationId)
                                    ));
                                } else {
                                    broadcastEvent(conversationId, "message_complete", Map.of(
                                            "status", persistStatus,
                                            "hasThinking", !accumulator.getThinking().isBlank(),
                                            "hasContent", !assistantText.isBlank()
                                    ));
                                    int msgCount = conversationService.getMessageCount(conversationId);
                                    broadcastEvent(conversationId, "done", buildDonePayload(
                                            conversationId, persistStatus, savedAssistant,
                                            accumulator.getPromptTokens(), accumulator.getCompletionTokens(),
                                            isAssistantPersisted(savedAssistant), msgCount));
                                }
                            } catch (Exception e) {
                                log.warn("SSE complete error: {}", e.getMessage());
                            } finally {
                                streamTracker.clearInterruptState(conversationId);
                                ChatStreamTracker.CompletionResult cr = streamTracker.completeAndConsumeIfLast(conversationId);
                                if (cr.allDone()) {
                                    // RFC follow-up (2026-04-27): the previous guard
                                    //   hasQueuedInput(conversationId) && (isInterruptFollowup || !wasStopped)
                                    // dropped legitimate queued messages when the user stopped
                                    // the running turn and then sent a new message via the
                                    // enqueue path (not the interrupt-with-followup path) —
                                    // wasStopped=true + isInterruptFollowup=false made the
                                    // guard false, the consumed queuedInput was discarded,
                                    // and the user's new message vanished. The other 4 sites
                                    // in this controller already use the simpler "if queued,
                                    // run it" condition; align with them. If the user
                                    // genuinely doesn't want continuation, no message would
                                    // have been in messageQueue to begin with.
                                    if (shouldDrainQueuedInput(conversationId, persistStatus)) {
                                        startQueuedMessage(conversationId, emitter, emitterDone, username, requestBaseUrl);
                                    } else {
                                        conversationService.updateStreamStatus(conversationId, "idle");
                                        // 延迟关闭 emitter，确保最后的事件都已发送
                                        sseExecutor.execute(() -> {
                                            try {
                                                Thread.sleep(100);
                                            } catch (InterruptedException ignored) {}
                                            completeEmitterQuietly(emitter, emitterDone);
                                        });
                                    }
                                } else {
                                    log.info("Original stream completed but replay still active, " +
                                            "keeping SSE emitter alive: conversationId={}", conversationId);
                                }
                            }
                        })
                        .doOnCancel(() -> {
                            boolean wasFirst = finalized.compareAndSet(false, true);
                            log.info("SSE doOnCancel fired: conversationId={}, wasFirst={}", conversationId, wasFirst);
                            if (!wasFirst) return;
                            // Force-recycle short-circuit: see doOnComplete above.
                            if (streamTracker.isRecycled(conversationId)) {
                                log.info("SSE doOnCancel skipped for force-recycled conversation: {}", conversationId);
                                streamTracker.clearInterruptState(conversationId);
                                try {
                                    conversationService.updateStreamStatus(conversationId, "idle");
                                } catch (Exception e) {
                                    log.debug("recycled-skip: stream_status reset failed for {}: {}",
                                            conversationId, e.getMessage());
                                }
                                ChatStreamTracker.CompletionResult cr = streamTracker.completeAndConsumeIfLast(conversationId);
                                if (cr.allDone()) {
                                    completeEmitterQuietly(emitter, emitterDone);
                                }
                                return;
                            }
                            // 区分用户主动停止和 interrupt-with-followup
                            ChatStreamTracker.InterruptType interruptType = streamTracker.getInterruptType(conversationId);
                            boolean isInterruptFollowup = interruptType == ChatStreamTracker.InterruptType.USER_INTERRUPT_WITH_FOLLOWUP;
                            String status = isInterruptFollowup ? "interrupted" : "stopped";

                            log.info("SSE stream cancelled ({}): conversationId={}", status, conversationId);
                            try {
                                MessageEntity savedAssistant = null;
                                List<MessageContentPart> assistantParts = accumulator.toAssistantParts();
                                String assistantText = accumulator.getContent();
                                if (!assistantText.isBlank() || !assistantParts.isEmpty()) {
                                    String savedText = assistantText.isBlank()
                                            ? (isInterruptFollowup ? "[已中断]" : "[已停止生成]") : assistantText;
                                    savedAssistant = conversationService.saveMessage(conversationId, "assistant", savedText, assistantParts,
                                            status,
                                            accumulator.getPromptTokens(),
                                            accumulator.getCompletionTokens(),
                                            accumulator.getCacheReadTokens(),
                                            accumulator.getCacheWriteTokens(),
                                            accumulator.getReasoningTokens(),
                                            accumulator.getRuntimeModelName(),
                                            accumulator.getRuntimeProviderId(),
                                            accumulator.toMetadataJson());
                                } else {
                                    savedAssistant = conversationService.saveMessage(conversationId, "assistant",
                                            isInterruptFollowup ? "[已中断]" : "[已停止生成]", null, status);
                                }

                                if (isInterruptFollowup) {
                                    broadcastEvent(conversationId, "message_complete", Map.of(
                                            "status", "interrupted",
                                            "hasThinking", !accumulator.getThinking().isBlank(),
                                            "hasContent", !assistantText.isBlank()
                                    ));
                                    broadcastEvent(conversationId, "turn_interrupted", Map.of(
                                            "conversationId", conversationId,
                                            "hasQueuedMessage", streamTracker.hasQueuedMessage(conversationId)
                                    ));
                                } else {
                                    broadcastEvent(conversationId, "message_complete", Map.of(
                                            "status", "stopped",
                                            "hasThinking", !accumulator.getThinking().isBlank(),
                                            "hasContent", !assistantText.isBlank()
                                    ));
                                    int stoppedMsgCount = conversationService.getMessageCount(conversationId);
                                    broadcastEvent(conversationId, "done", buildDonePayload(
                                            conversationId, "stopped", savedAssistant, 0, 0,
                                            isAssistantPersisted(savedAssistant), stoppedMsgCount));
                                }
                            } catch (Exception e) {
                                log.warn("SSE stop finalize error: {}", e.getMessage());
                            } finally {
                                streamTracker.clearInterruptState(conversationId);
                                ChatStreamTracker.CompletionResult cr = streamTracker.completeAndConsumeIfLast(conversationId);
                                if (cr.allDone()) {
                                    if (shouldDrainQueuedInput(conversationId, status)) {
                                        // 无论中断类型，都消费排队消息（修复 Disposable 不可用时队列被丢弃的 bug）
                                        startQueuedMessage(conversationId, emitter, emitterDone, username, requestBaseUrl);
                                    } else {
                                        conversationService.updateStreamStatus(conversationId, "idle");
                                        completeEmitterQuietly(emitter, emitterDone);
                                    }
                                }
                            }
                        })
                        .doOnError(e -> {
                            boolean wasFirst = finalized.compareAndSet(false, true);
                            if (!wasFirst) {
                                log.info("SSE doOnError skipped (finalized by doOnCancel): conversationId={}", conversationId);
                                return;
                            }
                            // Force-recycle short-circuit: see doOnComplete above.
                            if (streamTracker.isRecycled(conversationId)) {
                                log.info("SSE doOnError skipped for force-recycled conversation: {}, cause={}",
                                        conversationId, e.getMessage());
                                streamTracker.clearInterruptState(conversationId);
                                try {
                                    conversationService.updateStreamStatus(conversationId, "idle");
                                } catch (Exception ex) {
                                    log.debug("recycled-skip: stream_status reset failed for {}: {}",
                                            conversationId, ex.getMessage());
                                }
                                ChatStreamTracker.CompletionResult cr = streamTracker.completeAndConsumeIfLast(conversationId);
                                if (cr.allDone()) {
                                    completeEmitterQuietly(emitter, emitterDone);
                                }
                                return;
                            }

                            // CancellationException = 用户主动停止或中断续跑
                            boolean isUserStop = e instanceof java.util.concurrent.CancellationException
                                    || (e.getCause() instanceof java.util.concurrent.CancellationException);
                            ChatStreamTracker.InterruptType interruptType = streamTracker.getInterruptType(conversationId);
                            boolean isInterruptFollowup = interruptType == ChatStreamTracker.InterruptType.USER_INTERRUPT_WITH_FOLLOWUP;
                            // 三态：interrupted > stopped > failed
                            String status = !isUserStop ? "failed"
                                    : isInterruptFollowup ? "interrupted" : "stopped";

                            if (isInterruptFollowup) {
                                log.info("SSE stream interrupted for follow-up (CancellationException): conversationId={}", conversationId);
                            } else if (isUserStop) {
                                log.info("SSE stream stopped by user (CancellationException): conversationId={}", conversationId);
                            } else if (isClientDisconnect(e)) {
                                log.warn("SSE client disconnected: conversationId={}, cause={}", conversationId, e.getMessage());
                            } else {
                                log.error("SSE stream error: conversationId={}, cause={}", conversationId, e.getMessage());
                            }

                            try {
                                List<MessageContentPart> assistantParts = accumulator.toAssistantParts();
                                String assistantText = accumulator.getContent();
                                log.info("SSE doOnError saving: conversationId={}, status={}, textLen={}, partsCount={}",
                                        conversationId, status, assistantText.length(), assistantParts.size());
                                String errorMsg = e.getMessage() != null ? e.getMessage() : "unknown error";
                                MessageEntity savedAssistant = null;
                                if (!assistantText.isBlank() || !assistantParts.isEmpty()) {
                                    String savedText = assistantText.isBlank() && isUserStop
                                            ? (isInterruptFollowup ? "[已中断]" : "[已停止生成]") : assistantText;
                                    savedAssistant = conversationService.saveMessage(conversationId, "assistant", savedText, assistantParts,
                                            status,
                                            accumulator.getPromptTokens(),
                                            accumulator.getCompletionTokens(),
                                            accumulator.getCacheReadTokens(),
                                            accumulator.getCacheWriteTokens(),
                                            accumulator.getReasoningTokens(),
                                            accumulator.getRuntimeModelName(),
                                            accumulator.getRuntimeProviderId(),
                                            accumulator.toMetadataJson());
                                } else if (isUserStop) {
                                    savedAssistant = conversationService.saveMessage(conversationId, "assistant",
                                            isInterruptFollowup ? "[已中断]" : "[已停止生成]", null, status);
                                } else {
                                    savedAssistant = conversationService.saveMessage(conversationId, "assistant", "[错误] " + errorMsg, null, "failed");
                                }

                                if (isInterruptFollowup) {
                                    broadcastEvent(conversationId, "message_complete", Map.of(
                                            "status", "interrupted",
                                            "hasThinking", !accumulator.getThinking().isBlank(),
                                            "hasContent", !assistantText.isBlank()
                                    ));
                                    broadcastEvent(conversationId, "turn_interrupted", Map.of(
                                            "conversationId", conversationId,
                                            "hasQueuedMessage", streamTracker.hasQueuedMessage(conversationId)
                                    ));
                                } else if (isUserStop) {
                                    broadcastEvent(conversationId, "message_complete", Map.of(
                                            "status", "stopped",
                                            "hasThinking", !accumulator.getThinking().isBlank(),
                                            "hasContent", !assistantText.isBlank()
                                    ));
                                    int stoppedMsgCount = conversationService.getMessageCount(conversationId);
                                    broadcastEvent(conversationId, "done", buildDonePayload(
                                            conversationId, "stopped", savedAssistant, 0, 0,
                                            isAssistantPersisted(savedAssistant), stoppedMsgCount));
                                } else {
                                    broadcastEvent(conversationId, "error", buildErrorPayload(conversationId, errorMsg, savedAssistant));
                                }
                            } catch (Exception ioException) {
                                log.error("SSE doOnError save/broadcast failed: conversationId={}, error={}",
                                        conversationId, ioException.getMessage(), ioException);
                            }
                            streamTracker.clearInterruptState(conversationId);
                            ChatStreamTracker.CompletionResult cr = streamTracker.completeAndConsumeIfLast(conversationId);
                            log.info("SSE doOnError cleanup: conversationId={}, allDone={}, isInterruptFollowup={}, hasQueued={}",
                                    conversationId, cr.allDone(), isInterruptFollowup, hasQueuedInput(conversationId));
                            if (cr.allDone()) {
                                // RFC follow-up (2026-04-27): the previous guard
                                //   cr.queuedInput()!=null && !(isUserStop && !isInterruptFollowup)
                                // tried to suppress continuation when the user "explicitly
                                // stopped" without an interrupt-with-followup. But the
                                // frontend's enqueue path doesn't set interruptType — it
                                // just calls requestStop + offers to messageQueue. From the
                                // server's POV that's "isUserStop=true, isInterruptFollowup=
                                // false, queue has content", which the guard mis-classified
                                // as "abort" and silently dropped the user's freshly-typed
                                // follow-up. Whoever puts a message in messageQueue means it
                                // — just run it. Aligns with doOnComplete and the 4 other
                                // queue-launch sites in this controller.
                                if (shouldDrainQueuedInput(conversationId, status)) {
                                    startQueuedMessage(conversationId, emitter, emitterDone, username, requestBaseUrl);
                                } else {
                                    conversationService.updateStreamStatus(conversationId, "idle");
                                    completeEmitterQuietly(emitter, emitterDone);
                                }
                            }
                        })
                        .subscribe(
                                chunk -> { },
                                error -> log.debug("SSE stream subscription terminated with error: {}", error.getMessage()),
                                () -> log.debug("SSE stream subscription completed: conversationId={}", conversationId));

                // 将 Disposable 注册到 StreamTracker，以便 stop 端点可以取消它
                streamTracker.setDisposable(conversationId, disposable);
                // JVM 关闭时优雅落盘：避免 mvn spring-boot:run 重启 / SIGTERM 把
                // 进行中 turn 的 assistant 消息丢失（doOnError 来不及在 Hikari 关闭前执行）
                streamTracker.setEmergencySaveCallback(conversationId,
                        () -> emergencySaveAccumulator(conversationId, accumulator));

            } catch (Exception e) {
                log.error("SSE setup error: {}", e.getMessage());
                try {
                    broadcastEvent(conversationId, "error", Map.of("message", e.getMessage() != null ? e.getMessage() : "unknown error"));
                } catch (Exception ioException) {
                    log.warn("SSE setup failure event broadcast error: {}", ioException.getMessage());
                }
                streamTracker.complete(conversationId);
                conversationService.updateStreamStatus(conversationId, "idle");
                completeEmitterQuietly(emitter, emitterDone);
            }
        });

        return emitter;
        }
    }

@Override
    @SuppressWarnings("unchecked")
    public Map<String, Object> apply(OverAllState state) throws Exception {
        MateClawStateAccessor accessor = new MateClawStateAccessor(state);

        // ======= 取消检查（LLM 调用前，尚未计数） =======
        String conversationId = accessor.conversationId();
        if (streamTracker != null && streamTracker.isStopRequested(conversationId)) {
            log.info("[ReasoningNode] Stop requested before LLM call, aborting");
            throw new CancellationException("Stream stopped by user");
        }

        // ======= forced_tool_call 检测：审批通过后的重放（不计入 LLM 调用） =======
        String forcedToolCallJson = accessor.forcedToolCall();
        if (!forcedToolCallJson.isEmpty()) {
            try {
                log.info("[ReasoningNode] Detected forced_tool_call, skipping LLM, emitting tool call directly");

                AssistantMessage.ToolCall toolCall = deserializeToolCall(forcedToolCallJson);

                AssistantMessage syntheticMsg = AssistantMessage.builder()
                        .content("")
                        .toolCalls(List.of(toolCall))
                        .build();

                return reasonOutput()
                        .needsToolCall(true)
                        .toolCalls(List.of(toolCall))
                        .messages(List.of((Message) syntheticMsg))
                        .iterationCount(accessor.iterationCount() + 1)
                        .forcedToolCall("")
                        .currentPhase("forced_replay")
                        .contentStreamed(true)
                        .thinkingStreamed(true)
                        .events(List.of(GraphEventPublisher.phase("forced_replay", Map.of(
                                "toolName", toolCall.name(),
                                "iteration", accessor.iterationCount() + 1))))
                        .build();
            } catch (Exception e) {
                log.error("[ReasoningNode] Failed to deserialize forced_tool_call, falling through to normal LLM: {}",
                        e.getMessage());
            }
        }

        // ======= 构建 Prompt =======
        String systemPrompt = accessor.systemPrompt();
        // Tool-use enforcement is always appended: without it some models tend to
        // "narrate" instead of calling tools. The grounded contract (cite-or-refuse)
        // is appended only when the agent has a knowledge-base (wiki_*) tool bound,
        // so KB-grounded scenarios get strict source attribution while general
        // agents keep their normal answering behaviour.
        //
        // Appended at runtime rather than woven into the AgentEntity-stored
        // prompt so it stays out of the user-editable agent UI but is still
        // always-on for the runtime LLM.
        systemPrompt = buildGroundedSystemPrompt(systemPrompt, hasWikiTool());
        List<Message> messages = accessor.messages();

        // Per-loop budget: bound the working message list a single Reasoning
        // iteration hands to the LLM. The previous fixed head=4 + tail=36 cut
        // could lose the latest UserMessage once the ReAct loop accumulated
        // tool calls/observations past ~70 messages — the user's question
        // fell into the dropped middle, the LLM lost it, and the agent
        // answered off-topic. LoopMessageBudgeter anchors the latest
        // UserMessage as undroppable, sizes the tail by token budget instead
        // of message count, and keeps the same bidirectional tool-pair
        // integrity guard the old block already had. The L2 trim here is
        // distinct from ConversationWindowManager (L1): L1 runs once per
        // user turn and produces an LLM summary for multi-turn history; L2
        // runs per reasoning iteration on what L1 already produced plus
        // intra-turn tool-call growth.
        //
        // Reserved prefix tokens cover the non-history portion of the
        // prompt the LLM will receive: system prompt (with tool-use
        // enforcement already appended), tool schemas, output reserve,
        // and a buffer for skill catalog + runtime context + wiki
        // injections that are added downstream. Underestimating here only
        // delays the trigger slightly — invariants (anchor, pair integrity)
        // still hold once budget fires.
        int systemTokens = TokenEstimator.estimateTokens(systemPrompt);
        int toolsTokens = TokenEstimator.estimateToolsTokens(toolCallbacks);
        int loopReservedPrefixTokens = systemTokens + toolsTokens
                + maxOutputTokens + LOOP_PREFIX_AUXILIARY_RESERVE_TOKENS;
        LoopBudgetConfig loopCfg = LoopBudgetConfig.forContext(loopContextWindowTokens())
                .withReservedPrefixTokens(loopReservedPrefixTokens);
        LoopMessageBudgeter.Result budgeted = LOOP_BUDGETER.budget(messages, loopCfg);
        // Only log when the budget actually modified the list — a triggered-
        // but-no-op pass is normal (history fits comfortably under the tail
        // budget) and would otherwise spam logs every iteration.
        if (budgeted.trace().modified()) {
            LoopMessageBudgeter.BudgetTrace t = budgeted.trace();
            log.warn("[ReasoningNode] Loop budget trim: {} -> {} msgs (history {} -> {} tokens, "
                    + "prefix~{}), head={}, tail={}, droppedMiddle={}, orphans={}, "
                    + "anchorEnforced={}, anchorStitched={}, targetMaxTripped={}, "
                    + "capExceededForPairIntegrity={}, minTailFloorApplied={}, conv={}",
                    t.originalCount(), t.finalCount(), t.originalTokens(), t.finalTokens(),
                    t.reservedPrefixTokens(),
                    t.headKept(), t.tailKept(), t.droppedMiddle(), t.orphansRemoved(),
                    t.anchorEnforced(), t.anchorStitched(), t.targetMaxTripped(),
                    t.capExceededForPairIntegrity(), t.minTailFloorApplied(), conversationId);
        }
        messages = budgeted.messages();

        String workspaceBasePath = state.value(vip.mate.agent.graph.state.MateClawStateKeys.WORKSPACE_BASE_PATH, "");
        String agentIdStr = state.value(MateClawStateKeys.AGENT_ID, "");
        String userMsg = state.value(MateClawStateKeys.USER_MESSAGE, "");
        String runtimeModelName = state.value(MateClawStateKeys.RUNTIME_MODEL_NAME, "");
        String runtimeProviderId = state.value(MateClawStateKeys.RUNTIME_PROVIDER_ID, "");

        // Build the non-history prefix ONCE. The PTL retry branch below
        // reuses this list verbatim so the retried prompt has exactly the
        // same system / runtime context / wiki injection as the original —
        // the previous tail-only retry path silently dropped the wiki
        // segment which led to "answer regressed after compaction"
        // complaints on long sessions.
        List<Message> nonHistoryPrefix = buildNonHistoryPrefix(systemPrompt, workspaceBasePath, agentIdStr, userMsg,
                accessor.chatOrigin(), runtimeModelName, runtimeProviderId);

        // Append the skill catalog as a SEPARATE SystemMessage right after the
        // skeleton system prompt. Rendered with an empty loadedThisRun set so
        // the catalog content stays stable across turns — this lets the
        // system+catalog SystemMessage pair be served from the prompt cache
        // (Anthropic SYSTEM_AND_TOOLS / OpenAI prefix cache). The per-turn
        // "skills loaded this run" hint is injected separately as a volatile
        // suffix (after RuntimeContext) so it never invalidates the cached
        // prefix. Reused verbatim by the PTL retry branch.
        if (skillCatalogRenderer != null) {
            String staticCatalog = skillCatalogRenderer.render(java.util.Set.of());
            if (staticCatalog != null && !staticCatalog.isBlank()) {
                nonHistoryPrefix.add(1, new SystemMessage(staticCatalog));
            }
        }

        // Inject the conversation's progress-ledger snapshot as a separate
        // SystemMessage. Sits in nonHistoryPrefix (never trimmed) so the
        // agent always sees its own "what's done / what's pending" record
        // even after the message-window trim above drops the tool-call
        // history that produced those done entries. Suppressed when the
        // ledger column is empty so short single-turn questions stay
        // prompt-cache-friendly.
        //
        // Past iteration ~10, also emit a stale-reminder SystemMessage when
        // the ledger looks abandoned (empty after many turns, or no
        // progress_update in >90s). This pushes the model back to the
        // ledger discipline before it drifts into the "I'm doing the work
        // but never marking it" failure mode observed in round-4 of the
        // LLM-review smoke test.
        if (progressLedgerService != null && conversationId != null && !conversationId.isBlank()) {
            try {
                vip.mate.agent.progress.ProgressLedger ledger =
                        progressLedgerService.load(conversationId);
                String snapshot = ledger.renderSnapshot();
                if (snapshot != null) {
                    nonHistoryPrefix.add(new SystemMessage(snapshot));
                }
                String staleReminder = ledger.renderStaleReminder(
                        accessor.iterationCount(), java.time.Instant.now());
                if (staleReminder != null) {
                    nonHistoryPrefix.add(new SystemMessage(staleReminder));
                    log.info("[ReasoningNode] Injected stale-ledger reminder at iter {} for conv {}",
                            accessor.iterationCount(), conversationId);
                }
            } catch (Exception e) {
                // Never let a ledger-side failure break the reasoning step.
                log.warn("[ReasoningNode] Failed to load progress ledger for {}: {}",
                        conversationId, e.getMessage());
            }
        }

        // C4: drain any environment-change notifications that landed while
        // this conversation was running (MCP disconnect, skill update, etc.)
        // and inject them as a one-shot SystemMessage. Each notification is
        // delivered at most once — drain() empties the queue. Skipped when
        // the registry is absent (tests / legacy paths) or the conversation
        // has no pending notifications.
        if (runningConversationRegistry != null && conversationId != null && !conversationId.isBlank()) {
            try {
                List<vip.mate.agent.runtime.EnvironmentNotification> notes =
                        runningConversationRegistry.drain(conversationId);
                if (!notes.isEmpty()) {
                    String block = renderEnvironmentNotifications(notes);
                    if (block != null) {
                        nonHistoryPrefix.add(new SystemMessage(block));
                        log.info("[ReasoningNode] Injected {} environment notification(s) for conv {}",
                                notes.size(), conversationId);
                    }
                }
            } catch (Exception e) {
                log.warn("[ReasoningNode] Failed to drain environment notifications for {}: {}",
                        conversationId, e.getMessage());
            }
        }

        // Per-turn "skills loaded this run" hint — kept out of the stable
        // catalog segment (which is rendered with an empty loadedThisRun set
        // so it stays prompt-cache-friendly). Injected here as a volatile
        // suffix so the model still sees which skills it already pulled in
        // via load_skill this run, without invalidating the cached
        // system+catalog SystemMessage prefix.
        java.util.Set<String> loadedThisRun = accessor.loadedSkills();
        if (loadedThisRun != null && !loadedThisRun.isEmpty()) {
            String hint = renderLoadedSkillsHint(loadedThisRun);
            if (hint != null) {
                nonHistoryPrefix.add(new SystemMessage(hint));
            }
        }

        if (conversationWindowManager != null) {
            // Age-based compaction first: drop the body of tool responses
            // older than the K most recent into a one-line placeholder that
            // keeps the toolCallId / tool name (so the assistant/tool pair
            // stays valid) and, for spilled bodies, preserves the on-disk
            // path so read_file can still recover the original. Without
            // this, even spilled previews (~1-2 KB each) accumulate across
            // 30+ tool calls and bloat the prompt the model sees every turn.
            messages = conversationWindowManager.compactAgedToolResponses(
                    messages, KEEP_RECENT_TOOL_RESPONSES);
            // Pass conversationId + workspaceBasePath so oversized older
            // tool results can be spilled to the workspace spill directory
            // (preserving the full body for read_file recovery) instead of
            // being rewritten into a lossy single-line summary.
            messages = conversationWindowManager.pruneOldToolResultsForModelInput(
                    messages, conversationId, workspaceBasePath);
        }
        List<Message> promptMessages = new ArrayList<>(nonHistoryPrefix);
        promptMessages.addAll(messages);

        // 请求级思考深度覆盖（ThinkingLevelHolder 由 AgentService 设置）
        String effectiveReasoning = resolveEffectiveReasoningEffort();
        log.info("[ReasoningNode] thinkingLevel={}, effectiveReasoningEffort={}, nodeDefault={}",
                ThinkingLevelHolder.get(), effectiveReasoning, this.reasoningEffort);

        // Progressive disclosure: advertise only core tools plus the extensions
        // enabled this run, computed fresh each turn from ENABLED_EXTENSION_TOOLS
        // so an enable_tool call earlier in this loop takes effect immediately.
        // Falls back to the full tool set when no disclosure service is wired.
        List<ToolCallback> activeCallbacks = (toolDisclosureService != null && toolSet != null)
                ? toolDisclosureService.split(toolSet, accessor.enabledExtensionTools(), autoDemotedTools)
                        .activeCallbacks()
                : toolCallbacks;
        activeCallbacks = filterLongFormArtifactTools(accessor.userMessage(), activeCallbacks);

        ChatOptions options = buildChatOptions(effectiveReasoning, activeCallbacks);

        Prompt prompt = new Prompt(promptMessages, options);

        // Prefix accounting: how much of the window the never-trimmed prefix
        // (system prompt + runtime context + wiki + skill catalog + ledger)
        // and the advertised tool schemas consume. Logged on the turn's first
        // call so a small-window overflow is diagnosable per block instead of
        // surfacing as an opaque provider 400.
        int prefixEstimateTokens = TokenEstimator.estimateTokens(nonHistoryPrefix);
        int toolSchemaEstimateTokens = TokenEstimator.estimateToolsTokens(activeCallbacks);
        if (accessor.llmCallCount() == 0) {
            log.info("[ReasoningNode] Prefix accounting conv={}: window={} tokens, prefix={} "
                            + "(system+context+wiki+skills+ledger), toolSchemas={}, history={}",
                    conversationId, loopContextWindowTokens(), prefixEstimateTokens,
                    toolSchemaEstimateTokens, TokenEstimator.estimateTokens(messages));
        }
        // The prefix cannot be compacted (history compaction is the only lever),
        // so a prefix that alone exceeds the window makes the request doomed —
        // fail fast with the same PROMPT_TOO_LONG shape a provider rejection
        // would produce instead of sending it. Gated on budgeting being active
        // (an estimation false-positive must not block requests otherwise).
        boolean prefixOverflow = prefixBudgetPlan != null && prefixBudgetPlan.enabled()
                && prefixEstimateTokens + toolSchemaEstimateTokens > prefixBudgetPlan.effectiveMaxTokens();

        // ======= LLM 调用区域 =======
        // nextLlmCallCount 在首次 streamCall 之前计算。
        // 所有退出路径（正常、stopped、fatal error、CancellationException）都必须写回此值。
        // PTL compact retry 会再 +1。
        int nextLlmCallCount = accessor.llmCallCount() + 1;
        log.debug("[ReasoningNode] Calling LLM with {} messages, {} tool definitions, iteration {}/{}, llmCallCount={}",
                promptMessages.size(), activeCallbacks.size(),
                accessor.iterationCount(), accessor.maxIterations(), nextLlmCallCount);

        GraphEventPublisher.GraphEvent phaseEvent = GraphEventPublisher.phase("reasoning",
                Map.of("iteration", accessor.iterationCount()));
        // Iteration boundary marker for the parent ReAct loop. Reason
        // distinguishes the very first turn of the conversation from a
        // mid-loop repeat for consumers grouping events into per-turn cards.
        boolean iterationEventsOn = streamTracker == null || streamTracker.isIterationEventsEnabled();
        GraphEventPublisher.GraphEvent iterStartEvent = iterationEventsOn
                ? GraphEventPublisher.iterationStart(
                        accessor.iterationCount(),
                        accessor.iterationCount() == 0 ? "first_turn" : "react_step",
                        "parent",
                        null)
                : null;
        pushPhase(conversationId, "reasoning", Map.of(
                "iteration", accessor.iterationCount(),
                "llmCallCount", nextLlmCallCount
        ));

        NodeStreamingChatHelper.StreamResult result;
        try {
            if (prefixOverflow) {
                String overflowMessage = "Prompt 前缀估算 " + (prefixEstimateTokens + toolSchemaEstimateTokens)
                        + " tokens(注入块 " + prefixEstimateTokens + " + 工具 schema " + toolSchemaEstimateTokens
                        + ")已超过模型上下文窗口 " + prefixBudgetPlan.effectiveMaxTokens()
                        + " tokens,历史压缩无法解决——请精简 Agent 身份 prompt、减少绑定工具/技能,"
                        + "或换用更大窗口的模型";
                log.error("[ReasoningNode] {}", overflowMessage);
                result = new NodeStreamingChatHelper.StreamResult(null, null, null, List.of(), false,
                        0, 0, false, overflowMessage,
                        NodeStreamingChatHelper.ErrorType.PROMPT_TOO_LONG, false, 0, 0, 0);
            } else {
                result = streamingHelper.streamCall(chatModel, prompt, conversationId, "reasoning");
            }

            // PTL 处理：结构化压缩后重试。复用 nonHistoryPrefix 保证重试
            // Prompt 仍带 wiki / runtime context；早期的 tail-only 路径会把
            // wiki 段一起丢掉，重试后的 prompt 比原始更短少一层信息。
            if (result.isPromptTooLong() && conversationWindowManager != null) {
                log.warn("[ReasoningNode] Prompt too long, attempting STRUCTURED compaction and retry");

                // MateClawStateAccessor.agentId() returns String per state
                // schema; the ConversationWindowManager hook expects Long
                // (nullable — onPreCompress is a no-op when null).
                Long agentIdLong = null;
                if (!agentIdStr.isEmpty()) {
                    try {
                        agentIdLong = Long.parseLong(agentIdStr);
                    } catch (NumberFormatException ignored) {
                        // Same fallback as the non-history prefix builder above.
                    }
                }

                List<Message> compactedMessages = conversationWindowManager.compactForRetry(
                        messages, chatModel, conversationId, agentIdLong);

                if (compactedMessages != null && compactedMessages.size() < messages.size()) {
                    // Reuse the SAME non-history prefix — wiki/runtime context preserved.
                    List<Message> retryPromptMessages = new ArrayList<>(nonHistoryPrefix);
                    retryPromptMessages.addAll(compactedMessages);
                    Prompt retryPrompt = new Prompt(retryPromptMessages, options);
                    log.info("[ReasoningNode] Retrying with compacted messages: {} -> {} messages",
                            messages.size(), compactedMessages.size());
                    nextLlmCallCount++;
                    pushPhase(conversationId, "reasoning", Map.of(
                            "iteration", accessor.iterationCount(),
                            "llmCallCount", nextLlmCallCount,
                            "compacted", true
                    ));
                    result = streamingHelper.streamCall(chatModel, retryPrompt, conversationId, "reasoning_compact_retry");
                } else {
                    log.warn("[ReasoningNode] Compaction did not reduce messages, cannot retry");
                }
            }

            // Continuation guard: a no-tool-call turn with no visible content is
            // not a real answer, whether it is fully blank or carries only
            // reasoning. The final-answer branch would otherwise treat it as
            // "done" (finalAnswer="") and end the run prematurely. Two shapes:
            //   BLANK         — no content, no thinking, no tool call. Seen under
            //                   heavy message-window trimming on long multi-step
            //                   tasks (a 10-item research task stopping at item 2).
            //   THINKING_ONLY — reasoning present but no content and no tool call.
            //                   Interleaved-thinking models "decide" they are done
            //                   in their reasoning yet never emit the answer text;
            //                   most often right after a tool result (e.g. a
            //                   send-file tool succeeds but the download URL is
            //                   never written, so the user has to send another
            //                   message to resume).
            // Re-prompt to continue — bounded, so a model that genuinely has
            // nothing left still terminates cleanly through the normal
            // empty-answer path below. When the newest turn is a tool result, an
            // answer-anchored nudge recovers the user-facing reply in the same run.
            int emptyRetries = 0;
            for (ContinuationIntent intent = classifyContinuation(result);
                    emptyRetries < MAX_EMPTY_COMPLETION_RETRIES && intent != ContinuationIntent.FINAL;
                    intent = classifyContinuation(result)) {
                emptyRetries++;
                boolean afterTool = lastTurnIsToolResponse(promptMessages);
                String nudge = afterTool
                        ? POST_TOOL_EMPTY_NUDGE
                        : (intent == ContinuationIntent.THINKING_ONLY
                                ? THINKING_ONLY_NUDGE
                                : EMPTY_COMPLETION_NUDGE);
                log.warn("[ReasoningNode] {} completion (afterTool={}); nudging to continue "
                                + "(retry {}/{}), conv={}",
                        intent, afterTool, emptyRetries, MAX_EMPTY_COMPLETION_RETRIES, conversationId);
                List<Message> nudgedMessages = new ArrayList<>(promptMessages);
                nudgedMessages.add(new UserMessage(nudge));
                Prompt nudgePrompt = new Prompt(nudgedMessages, options);
                nextLlmCallCount++;
                result = streamingHelper.streamCall(
                        chatModel, nudgePrompt, conversationId, "reasoning_empty_retry");
            }
        } catch (CancellationException ce) {
            // "调用已发出但尚未产出内容时用户停止" — streamHelper 抛 CancellationException。
            // 返回空 finalAnswer + STOPPED，让 FinalAnswerNode 按 STOPPED 语义处理。
            // 必须显式清零 needsToolCall/shouldSummarize，防止前一轮残留标志导致误路由。
            log.info("[ReasoningNode] CancellationException during LLM call (user stopped before first token), " +
                    "returning empty answer with STOPPED, llmCallCount={}", nextLlmCallCount);
            return reasonOutput()
                    .finalAnswer("")
                    .needsToolCall(false)
                    .shouldSummarize(false)
                    .llmCallCount(nextLlmCallCount)
                    .finishReason(FinishReason.STOPPED)
                    .contentStreamed(true)
                    .thinkingStreamed(true)
                    .build();
        }

        // ======= 处理 StreamResult =======

        // 用户主动停止且有部分内容
        if (result.stopped() && result.hasAnyContent()) {
            String partialText = result.text() != null ? result.text() : "";
            String partialThinking = result.thinking() != null ? result.thinking() : "";
            log.info("[ReasoningNode] Stop with partial content ({} chars, thinking {} chars), flushing as final answer",
                    partialText.length(), partialThinking.length());
            var builder = reasonOutput()
                    .finalAnswer(partialText)
                    .needsToolCall(false)
                    .shouldSummarize(false)
                    .contentStreamed(true)
                    .llmCallCount(nextLlmCallCount)
                    .mergeUsage(state, result)
                    .finishReason(FinishReason.STOPPED);
            if (!partialThinking.isEmpty()) {
                builder.finalThinking(partialThinking);
                builder.thinkingStreamed(true);
            }
            return builder.build();
        }

        // Order matters: the partial-truncation branch MUST sit before
        // hasFatalError(). hasFatalError() is "no text + no tool calls + non-
        // null errorMessage", which is also the shape of a thinking-only cap
        // result (text is empty by definition). Without this ordering the
        // soft cap would be re-promoted to ERROR_FALLBACK and we'd lose the
        // INCOMPLETE semantics.

        if (result.partial() && "thinking_only_no_content".equals(result.errorMessage())) {
            // Soft thinking-only loop: the helper disposed the upstream stream
            // because the model accumulated >= THINKING_ONLY_HARD_CAP_CHARS of
            // reasoning_content without emitting any visible content or tool
            // calls. Treat as INCOMPLETE rather than fatal — the thinking text
            // has already been streamed and is preserved for the UI's collapse
            // panel; the user gets a short fallback line they can retry from.
            String partialThinking = result.thinking() != null ? result.thinking() : "";
            log.warn("[ReasoningNode] Thinking-only soft cap hit ({} thinking chars, no content/tools); " +
                            "INCOMPLETE",
                    partialThinking.length());
            var builder = reasonOutput()
                    .needsToolCall(false)
                    .shouldSummarize(false)
                    .finalAnswer("（模型在思考阶段停留过久且未给出最终答案，请重试或拆分问题。）")
                    .llmCallCount(nextLlmCallCount)
                    .finishReason(FinishReason.INCOMPLETE)
                    .contentStreamed(false)
                    .thinkingStreamed(true)
                    .mergeUsage(state, result);
            if (!partialThinking.isEmpty()) {
                builder.finalThinking(partialThinking);
            }
            return builder.build();
        }

        if (result.partial() && "content_repetition".equals(result.errorMessage())) {
            // Reasoning loop: the helper disposed the stream because the
            // model emitted the same paragraph 4+ times in a row (qwen3.6
            // / deepseek-r1 self-arguing pattern). The streamed text
            // already showed the duplicates to the user — we can't unsend
            // SSE chunks — but the persisted finalAnswer should be ONE
            // clean copy so the IM channel reply and any page-reload
            // history don't show the wall of repetition. Skip
            // FinalAnswerNode's evidence validation: the answer is
            // already truncated, applying validateAnswer on top would
            // double-stamp warnings on something the user already knows
            // is incomplete.
            String rawContent = result.text() != null ? result.text() : "";
            String dedupedAnswer = NodeStreamingChatHelper.dedupTrailingRepeats(
                    rawContent,
                    NodeStreamingChatHelper.CONTENT_REPEAT_MIN_PERIOD,
                    NodeStreamingChatHelper.CONTENT_REPEAT_MAX_PERIOD);
            log.warn("[ReasoningNode] Content-repetition cap hit (raw={} chars → deduped={} chars); " +
                            "INCOMPLETE",
                    rawContent.length(), dedupedAnswer.length());
            var builder = reasonOutput()
                    .needsToolCall(false)
                    .shouldSummarize(false)
                    .finalAnswer(dedupedAnswer.isEmpty()
                            ? "（模型反复输出同一段内容，已自动截断。请尝试重新生成或换个问法。）"
                            : dedupedAnswer)
                    .llmCallCount(nextLlmCallCount)
                    .finishReason(FinishReason.INCOMPLETE)
                    // contentStreamed=true because the user already saw
                    // the looping text in their bubble; persisting again
                    // via streamedContent would replay it.
                    .contentStreamed(true)
                    .thinkingStreamed(result.thinking() != null && !result.thinking().isEmpty())
                    .mergeUsage(state, result);
            if (result.thinking() != null && !result.thinking().isEmpty()) {
                builder.finalThinking(result.thinking());
            }
            return builder.build();
        }

        // Fatal error：直接设置 finalAnswer 为错误文案 + ERROR_FALLBACK，
        // 不走 LimitExceededNode（后者会再发一次 LLM 调用，语义不对且对认证/配额错误会再失败）。
        // ReasoningDispatcher 看到 !needsToolCall && !shouldSummarize → finalAnswerNode，
        // FinalAnswerNode 检测到 existingAnswer 非空时直接使用，finishReason 保持 ERROR_FALLBACK。
        if (result.hasFatalError()) {
            log.error("[ReasoningNode] Fatal LLM error: {}", result.errorMessage());
            return reasonOutput()
                    .needsToolCall(false)
                    .shouldSummarize(false)
                    .finalAnswer("[错误] " + result.errorMessage())
                    .llmCallCount(nextLlmCallCount)
                    .finishReason(FinishReason.ERROR_FALLBACK)
                    .contentStreamed(true)
                    .thinkingStreamed(true)
                    .mergeUsage(state, result)
                    .build();
        }

        // Compatibility safety net for providers/adapters that return the
        // runtime's reserved error placeholder as an HTTP-successful content
        // response. Without this guard the long-form completion gate treats
        // the placeholder as a short draft and can repeat it until the graph's
        // iteration cap. Cron and other synchronous callers consume the
        // resulting structured ERROR_FALLBACK; they do not need to infer from
        // user-facing text.
        if (isRuntimeErrorPlaceholder(result.text())) {
            String errorText = result.text();
            log.error("[ReasoningNode] Runtime error placeholder returned as normal content; failing turn");
            return reasonOutput()
                    .needsToolCall(false)
                    .shouldSummarize(false)
                    .finalAnswer(errorText)
                    .llmCallCount(nextLlmCallCount)
                    .finishReason(FinishReason.ERROR_FALLBACK)
                    .contentStreamed(true)
                    .thinkingStreamed(result.thinking() != null && !result.thinking().isEmpty())
                    .mergeUsage(state, result)
                    .build();
        }

        if (result.partial()) {
            int partialChars = result.text() != null ? result.text().length() : 0;
            log.warn("[ReasoningNode] Partial LLM result ({} chars), treating as final answer", partialChars);
        }

        if (result.hasToolCalls()) {
            if (hasDisallowedLongFormArtifactCall(accessor.userMessage(), result.toolCalls())) {
                log.warn("[ReasoningNode] Rejecting artifact tool call for plain long-form response: {}",
                        result.toolCalls().stream().map(AssistantMessage.ToolCall::name).toList());
                UserMessage continuation = new UserMessage("""
                        [Runtime long-form delivery gate]
                        The user requested the long-form text directly in chat and did not request a file,
                        document, attachment, export, or download. Do not call rendering or file-writing tools.
                        Continue writing the requested text directly in the response.
                        """);
                return reasonOutput()
                        .continueReasoning(true)
                        .iterationCount(accessor.iterationCount() + 1)
                        .needsToolCall(false)
                        .shouldSummarize(false)
                        .toolCalls(List.of())
                        .finalAnswer("")
                        .clearFinishReason()
                        .messages(List.of((Message) continuation))
                        .currentPhase("reasoning")
                        .streamedContent("")
                        .streamedThinking(result.thinking())
                        .contentStreamed(true)
                        .thinkingStreamed(!result.thinking().isEmpty())
                        .llmCallCount(nextLlmCallCount)
                        .mergeUsage(state, result)
                        .events(buildEvents(phaseEvent, iterStartEvent))
                        .build();
            }
            log.info("[ReasoningNode] LLM requested {} tool call(s): {}",
                    result.toolCalls().size(),
                    result.toolCalls().stream().map(AssistantMessage.ToolCall::name).toList());
            pushPhase(conversationId, "executing_tool", Map.of(
                    "iteration", accessor.iterationCount(),
                    "toolCount", result.toolCalls().size()
            ));

            return reasonOutput()
                    .needsToolCall(true)
                    .shouldSummarize(false)
                    .toolCalls(result.toolCalls())
                    .messages(List.of((Message) result.assistantMessage()))
                    .currentPhase("reasoning")
                    .currentThinking(result.thinking())
                    .streamedContent(result.text() != null ? result.text() : "")
                    .streamedThinking(result.thinking())
                    .contentStreamed(true)
                    .thinkingStreamed(!result.thinking().isEmpty())
                    .llmCallCount(nextLlmCallCount)
                    .mergeUsage(state, result)
                    .events(buildEvents(phaseEvent, iterStartEvent))
                    .build();
        } else {
            String content = result.text();
            ActionCompletionPolicy.Decision completionDecision = ActionCompletionPolicy.evaluate(
                    accessor.actionCompletionRequired(), accessor.actionCompletionRetryCount(),
                    accessor.actionExecutionLedger());
            if (completionDecision == ActionCompletionPolicy.Decision.RETRY) {
                log.warn("[ReasoningNode] Rejecting text-only action completion; continuing once");
                UserMessage continuation = new UserMessage("""
                        [Runtime completion gate]
                        This turn requires a real tool-backed action, but no substantive tool call was observed.
                        Continue now by emitting the required tool call. Do not claim success or only describe the call.
                        """);
                return reasonOutput()
                        .continueReasoning(true)
                        .actionCompletionRetryCount(accessor.actionCompletionRetryCount() + 1)
                        .needsToolCall(false)
                        .shouldSummarize(false)
                        .finalAnswer("")
                        .clearFinishReason()
                        .messages(List.of((Message) result.assistantMessage(), continuation))
                        .currentPhase("reasoning")
                        .streamedContent(content != null ? content : "")
                        .streamedThinking(result.thinking())
                        .contentStreamed(true)
                        .thinkingStreamed(!result.thinking().isEmpty())
                        .llmCallCount(nextLlmCallCount)
                        .mergeUsage(state, result)
                        .events(buildEvents(phaseEvent, iterStartEvent))
                        .build();
            }
            if (completionDecision == ActionCompletionPolicy.Decision.UNVERIFIED
                    || completionDecision == ActionCompletionPolicy.Decision.FAILED) {
                boolean failed = completionDecision == ActionCompletionPolicy.Decision.FAILED;
                String guardedAnswer = failed
                        ? "动作工具执行失败，未确认操作成功。请检查工具返回的错误后重试。"
                        : "未观察到实际的动作工具调用，因此没有执行或确认该操作。请重试。";
                log.warn("[ReasoningNode] Blocking unsupported action completion: {}", completionDecision);
                return reasonOutput()
                        .needsToolCall(false)
                        .shouldSummarize(false)
                        .finalAnswer(guardedAnswer)
                        .finalThinking(result.thinking())
                        .messages(List.of((Message) result.assistantMessage()))
                        .currentPhase("reasoning")
                        .streamedContent("")
                        .finishReason(failed ? FinishReason.ACTION_FAILED : FinishReason.ACTION_UNVERIFIED)
                        .contentStreamed(false)
                        .thinkingStreamed(!result.thinking().isEmpty())
                        .llmCallCount(nextLlmCallCount)
                        .mergeUsage(state, result)
                        .events(buildEvents(phaseEvent, iterStartEvent))
                        .build();
            }
            log.info("[ReasoningNode] LLM produced final answer ({} chars)", content != null ? content.length() : 0);
            if (shouldContinueLongForm(accessor.userMessage(), accessor.longFormDraft(), content,
                    accessor.iterationCount(), accessor.maxIterations())) {
                String accumulatedDraft = appendLongFormChunk(accessor.longFormDraft(), content);
                int written = accumulatedDraft.length();
                int requested = requestedLongFormChars(accessor.userMessage()).orElse(0);
                log.info("[ReasoningNode] Long-form answer below requested length ({} / {} chars), continuing",
                        written, requested);
                return reasonOutput()
                        .continueReasoning(true)
                        .iterationCount(accessor.iterationCount() + 1)
                        .needsToolCall(false)
                        .shouldSummarize(false)
                        .finalAnswer("")
                        .longFormDraft(accumulatedDraft)
                        .clearFinishReason()
                        .messages(List.of((Message) result.assistantMessage(),
                                longFormContinuationPrompt(accessor.userMessage(), accessor.longFormDraft(), content)))
                        .currentPhase("reasoning")
                        .streamedContent(content != null ? content : "")
                        .streamedThinking(result.thinking())
                        .contentStreamed(true)
                        .thinkingStreamed(!result.thinking().isEmpty())
                        .llmCallCount(nextLlmCallCount)
                        .mergeUsage(state, result)
                        .events(buildEvents(phaseEvent, iterStartEvent))
                        .build();
            }
            pushPhase(conversationId, "drafting_answer", Map.of(
                    "iteration", accessor.iterationCount(),
                    "answerChars", content != null ? content.length() : 0
            ));
            boolean longFormRequest = requestedLongFormChars(accessor.userMessage()).isPresent();
            String accumulatedContent = longFormRequest
                    ? appendLongFormChunk(accessor.longFormDraft(), content)
                    : (content != null ? content : "");
            String answerWithSources = accessor.sourceEvidenceLedger()
                    .appendWikiSourceTable(accumulatedContent);
            SourceEvidenceLedger.Validation validation =
                    accessor.sourceEvidenceLedger().validateAnswer(answerWithSources);
            boolean evidenceInsufficient = !validation.valid();
            String finalAnswer = evidenceInsufficient
                    ? evidenceWarning(validation.unsupportedReferences())
                    : answerWithSources;
            if (evidenceInsufficient) {
                log.warn("[ReasoningNode] Evidence insufficient for final answer, unsupportedReferences={}",
                        validation.unsupportedReferences());
            }

            // Final-answer path: iteration ends in this same node because
            // ReAct never re-enters the loop afterwards.
            GraphEventPublisher.GraphEvent iterEndEvent = iterationEventsOn
                    ? GraphEventPublisher.iterationEnd(accessor.iterationCount(),
                            "parent", null,
                            content != null ? content.length() : 0,
                            result.thinking() != null ? result.thinking().length() : 0)
                    : null;
            return reasonOutput()
                    .needsToolCall(false)
                    .shouldSummarize(false)
                    .finalAnswer(finalAnswer)
                    .finalThinking(result.thinking())
                    .messages(List.of((Message) result.assistantMessage()))
                    .currentPhase("reasoning")
                    .streamedContent(evidenceInsufficient ? accumulatedContent : "")
                    .finishReason(evidenceInsufficient ? FinishReason.EVIDENCE_INSUFFICIENT : FinishReason.NORMAL)
                    .contentStreamed(!evidenceInsufficient && Objects.equals(answerWithSources, accumulatedContent))
                    .thinkingStreamed(!result.thinking().isEmpty())
                    .llmCallCount(nextLlmCallCount)
                    .mergeUsage(state, result)
                    .events(buildEvents(phaseEvent, iterStartEvent, iterEndEvent))
                    .build();
        }
    }

