static OpenAiApi.ChatCompletionRequest patchReasoningContent(
            OpenAiApi.ChatCompletionRequest request, ModelProviderEntity provider) {
        if (request.messages() == null || request.messages().isEmpty()) {
            return request;
        }

        // 1. Consume relay (if any) and compute the sanitized user field.
        AssistantThinkingRelay.RelayEntry entry = AssistantThinkingRelay.take(request.user());
        String sanitizedUser = (entry != null)
                ? entry.originalUser()
                : (AssistantThinkingRelay.isToken(request.user()) ? null : request.user());

        // 2. Detect thinking mode — relay presence is also a trigger.
        boolean thinkingMode = request.reasoningEffort() != null
                || requiresReasoningContentPatch(request.model())
                || request.messages().stream().anyMatch(m ->
                        m.role() == OpenAiApi.ChatCompletionMessage.Role.ASSISTANT
                                && m.reasoningContent() != null)
                || entry != null;
        if (!thinkingMode) {
            // Nothing to patch but we may still need to strip a leaked relay token from user.
            return request.user() != null && !request.user().equals(sanitizedUser)
                    ? rebuildWithUser(request, sanitizedUser)
                    : request;
        }

        // 3. Find lastUserIdx so we can skip cross-turn assistants.
        int lastUserIdx = -1;
        for (int i = request.messages().size() - 1; i >= 0; i--) {
            if (request.messages().get(i).role() == OpenAiApi.ChatCompletionMessage.Role.USER) {
                lastUserIdx = i;
                break;
            }
        }

        FallbackPolicy policy = FallbackPolicy.forProvider(provider);
        java.util.Iterator<String> it = (entry != null)
                ? entry.thinkings().iterator()
                : java.util.Collections.emptyIterator();

        // 4. Walk messages, patching only in-turn assistants; always advance iterator
        //    for all assistants so producer/consumer positions stay aligned.
        boolean anyPatched = false;
        List<OpenAiApi.ChatCompletionMessage> patched = new ArrayList<>(request.messages().size());
        for (int i = 0; i < request.messages().size(); i++) {
            OpenAiApi.ChatCompletionMessage msg = request.messages().get(i);
            if (msg.role() != OpenAiApi.ChatCompletionMessage.Role.ASSISTANT) {
                patched.add(msg);
                continue;
            }

            String next = it.hasNext() ? it.next() : null;

            // Already has a real value: leave alone
            if (msg.reasoningContent() != null && !msg.reasoningContent().isBlank()) {
                patched.add(msg);
                continue;
            }

            // Cross-turn assistant: usually skipped, since thinking resets across
            // user turns. But some providers require reasoning_content even on
            // prior-turn assistants and reject requests where any prior assistant
            // has it null. For policies with patchCrossTurn=true, fall through and
            // patch with the empty fallback (" ") so multi-turn conversations
            // don't 400.
            if (i <= lastUserIdx && !policy.patchCrossTurn) {
                patched.add(msg);
                continue;
            }

            boolean hasToolCalls = msg.toolCalls() != null && !msg.toolCalls().isEmpty();
            if (!hasToolCalls && !policy.patchNonToolCall) {
                patched.add(msg);
                continue;
            }

            String injected;
            if (next != null && !next.isEmpty()) {
                injected = next;
            } else {
                // For cross-turn messages, try the reasoning content cache
                // (real values from prior responses) before falling back to empty.
                injected = resolveCrossTurnReasoning(msg, i <= lastUserIdx);
                if (injected == null) {
                    injected = policy.emptyFallback;
                    if (injected == null && policy.warnOnMissingReal) {
                        log.warn("[patchReasoningContent] provider={} requires real reasoning_content "
                                        + "but relay has no value for assistant message at index {}; "
                                        + "leaving null so provider returns explicit error.",
                                providerIdOrUnknown(provider), i);
                    }
                }
            }
            if (injected == null && msg.reasoningContent() == null) {
                // No change — keep original
                patched.add(msg);
                continue;
            }
            patched.add(new OpenAiApi.ChatCompletionMessage(
                    msg.rawContent(), msg.role(), msg.name(), msg.toolCallId(),
                    msg.toolCalls(), msg.refusal(), msg.audioOutput(),
                    msg.annotations(), injected));
            anyPatched = true;
        }

        boolean userChanged = request.user() != null && !request.user().equals(sanitizedUser)
                || (request.user() == null && sanitizedUser != null);
        if (!anyPatched && !userChanged) {
            return request;
        }

        // 5. Rebuild with patched messages + sanitized user.
        return new OpenAiApi.ChatCompletionRequest(
                patched,
                request.model(),
                request.store(),
                request.metadata(),
                request.frequencyPenalty(),
                request.logitBias(),
                request.logprobs(),
                request.topLogprobs(),
                request.maxTokens(),
                request.maxCompletionTokens(),
                request.n(),
                request.outputModalities(),
                request.audioParameters(),
                request.presencePenalty(),
                request.responseFormat(),
                request.seed(),
                request.serviceTier(),
                request.stop(),
                request.stream(),
                request.streamOptions(),
                request.temperature(),
                request.topP(),
                request.tools(),
                request.toolChoice(),
                request.parallelToolCalls(),
                sanitizedUser,
                request.reasoningEffort(),
                request.webSearchOptions(),
                request.verbosity(),
                request.promptCacheKey(),
                request.safetyIdentifier(),
                request.extraBody()
        );
    }

public BaseAgent build(AgentEntity entity, String modelProvider, String modelName) {
        AgentToolSet toolSet = toolRegistry.getEnabledToolSet();

        // Move 6 — Permission flattening at build time.
        //
        // Two layers of tool filtering exist in MateClaw:
        //   (1) Build-time filter (HERE) — decides which tools the model SEES
        //       in the tool list. Computed once per agent build; stable for
        //       the agent's lifecycle unless bindings change.
        //   (2) Runtime guard (ToolGuardService.evaluate) — decides which
        //       tools the model can CALL. Runs on every invocation; checks
        //       workspace boundaries, sensitive paths, credential exposure,
        //       shell command patterns, and approval workflows. All dynamic
        //       (depends on tool arguments, not just tool name).
        //
        // The build-time filter previously ran as 4 separate passes
        // (deny → allow → deny → exclude). Move 6 consolidates them into
        // a single deny-set + a single allow-set, applied in two passes:
        //   denied = global denied ∪ skill-discovery denied ∪ {load_skill if disabled}
        //   allowed = agent's bound tools (null = global default)
        Set<String> deniedTools = new java.util.LinkedHashSet<>(
                toolGuardConfigService.getDeniedTools());
        deniedTools.addAll(agentBindingService.getSkillDiscoveryDeniedTools(entity.getId()));
        if (!loadSkillToolEnabled) {
            deniedTools.add("load_skill");
        }
        toolSet = toolSet.withDeniedToolsFiltered(deniedTools);

        // RFC-090 §14.2 — single entry point that merges:
        //   (a) tools expanded from bound skills' active features, and
        //   (b) directly bound atomic tools (the Advanced bypass, §9.2 调整 B).
        // Three-state semantics: null = no agent-level restriction (use
        // global default); non-null (possibly empty) = explicit allowlist.
        Set<String> boundTools = agentBindingService.getEffectiveToolNames(entity.getId());
        toolSet = toolSet.withAllowedToolsOnly(boundTools); // null = 全局默认

        // Resolve the base model with the precedence: per-conversation pin >
        // per-Agent model override > global default. resolveRuntimeBaseModel
        // looks up enabled-only models and silently degrades an unmatched pin /
        // override to the global default, preserving the legacy behaviour for
        // Agents and conversations without an explicit choice.
        ModelConfigEntity globalDefault;
        boolean explicitPinHonoured;
        boolean agentOverrideHonoured;
        try {
            explicitPinHonoured = pinResolvesToEnabledModel(modelProvider, modelName);
            globalDefault = resolveRuntimeBaseModel(modelProvider, modelName, entity.getModelName());
            agentOverrideHonoured = !explicitPinHonoured
                    && agentModelOverrideResolved(entity, globalDefault);
        } catch (Exception e) {
            throw new MateClawException("err.agent.no_default_model", "无法构建 Agent：请先在「设置 → 模型」中配置并启用默认模型");
        }
        ModelConfigEntity runtimeModel;
        if (explicitPinHonoured || agentOverrideHonoured) {
            // The caller (admin UI / chat console) handed us a concrete
            // (provider, model) pin and it points to an enabled row. Honour
            // it verbatim — running providerRouter.selectPrimary here would
            // silently swap to a different model whenever a bound skill
            // advertised a capability gap, which is exactly the "I switched
            // model but the agent kept using the old one" surface. The
            // diagnostic below still surfaces capability gaps in the logs
            // so operators can see if the pinned model misses a need.
            runtimeModel = globalDefault;
        } else {
            try {
                runtimeModel = providerRouter.selectPrimary(entity.getId(), globalDefault);
                if (runtimeModel == null) runtimeModel = globalDefault;
            } catch (Exception e) {
                log.debug("[ProviderRouter] primary selection failed, falling back to global default: {}",
                        e.getMessage());
                runtimeModel = globalDefault;
            }
        }
        // Even after the upgrade, log a WARN when the chosen primary
        // still doesn't satisfy needs (e.g. no preferred provider was
        // capable). The diagnostic is observability-only.
        try {
            providerRouter.diagnosePrimary(entity.getId(), runtimeModel);
        } catch (Exception e) {
            log.debug("[ProviderRouter] diagnostic failed: {}", e.getMessage());
        }

        ModelProviderEntity provider;
        try {
            provider = modelProviderService.getProviderConfig(runtimeModel.getProvider());
        } catch (Exception e) {
            throw new MateClawException("err.agent.model_not_configured", "模型 " + runtimeModel.getModelName()
                    + " 的 Provider（" + runtimeModel.getProvider() + "）未配置，请检查模型设置");
        }

        // Safety net: getDefaultModel() already skips unconfigured providers, but guard here
        // too so a stale cached model doesn't silently proceed to a broken API call.
        if (!modelProviderService.isProviderConfigured(provider.getProviderId())) {
            String reason = modelProviderService.getProviderUnavailableReason(provider.getProviderId());
            log.warn("Runtime model {}/{} provider not configured ({}); trying fallback",
                    runtimeModel.getProvider(), runtimeModel.getModelName(), reason);
            ModelConfigEntity fallback = findFirstAvailableChatModel();
            if (fallback == null) {
                throw new MateClawException("err.agent.no_configured_model",
                        "默认模型 Provider「" + runtimeModel.getProvider() + "」未配置（" + reason
                        + "），且找不到其他已配置的 Provider，请先在「设置 → 模型」中完成配置");
            }
            runtimeModel = fallback;
            try {
                provider = modelProviderService.getProviderConfig(runtimeModel.getProvider());
            } catch (Exception e) {
                throw new MateClawException("err.agent.model_not_configured", "备用模型 " + runtimeModel.getModelName()
                        + " 的 Provider（" + runtimeModel.getProvider() + "）获取失败");
            }
        }

        ModelProtocol protocol = ModelProtocol.fromChatModel(provider.getChatModel());

        // Effective context window: explicit config > local-server probe > null
        // (downstream keeps its global-default fallback). Without probing, a
        // local 8k/16k model with maxInputTokens unset budgets against the
        // 128k global default and the first oversized request fails outright.
        Integer effectiveMaxInputTokens = contextWindowResolver.resolveMaxInputTokens(provider, runtimeModel);

        // 内置搜索检测（DashScope / Kimi），但不再移除 WebSearchTool — 两者协同而非互斥
        boolean builtinSearchEnabled = false;
        Map<String, Object> providerKwargs = modelProviderService.readProviderGenerateKwargs(provider);
        if (protocol == ModelProtocol.DASHSCOPE_NATIVE) {
            builtinSearchEnabled = dashScopeBuilder.isBuiltinSearchEnabled(runtimeModel, provider);
        } else if (OpenAiCompatibleChatModelBuilder.isKimiProvider(provider)
                && Boolean.TRUE.equals(ProviderGenerateKwargs.findOptionValue(providerKwargs, "enableSearch"))) {
            builtinSearchEnabled = true;
        }
        if (builtinSearchEnabled) {
            // Phase 2: 不再移除 search 工具，改为在 prompt 中设定优先级引导
            // 内置搜索作为首选，search 工具作为补充/兜底
            log.info("内置搜索已开启 (provider={})，search 工具保留作为补充通道", provider.getProviderId());
        }
        // Default 100 if DB row leaves max_iterations null. Negative or zero is an
        // explicit opt-in to "no soft cap" — ObservationDispatcher already treats
        // maxIterations<=0 as "do not enforce", so the agent runs until the LLM
        // emits a final answer (or returnDirect short-circuits). Positive values
        // are clamped to the hard ceiling so a misconfigured row can't skip the
        // safety net unintentionally.
        int rawMaxIter = entity.getMaxIterations() != null ? entity.getMaxIterations() : 100;
        int maxIter;
        if (rawMaxIter <= 0) {
            maxIter = 0;
            log.info("Agent {} max_iterations={} → unlimited soft cap (LLM controls termination)",
                    entity.getId(), rawMaxIter);
        } else {
            maxIter = Math.min(rawMaxIter, BaseAgent.MAX_ITERATIONS_HARD_CEILING);
            if (maxIter != rawMaxIter) {
                log.warn("Agent {} max_iterations={} clamped to {} (1..{})",
                        entity.getId(), rawMaxIter, maxIter, BaseAgent.MAX_ITERATIONS_HARD_CEILING);
            }
        }

        // Prefix injection budget: optional blocks (memory / wiki / skill
        // catalog / extension catalog / ledger) share a token budget scaled
        // to the model's effective window. The agent's own prompt and the
        // tool schemas are never truncated — they are subtracted from the
        // budget so the optional blocks absorb the squeeze.
        int basePromptTokens = TokenEstimator.estimateTokens(entity.getSystemPrompt());
        int toolSchemaTokens = TokenEstimator.estimateToolsTokens(toolSet.callbacks());
        PrefixBudgetPlan prefixBudgetPlan = prefixBudgetPlanner.plan(
                effectiveMaxInputTokens, basePromptTokens, toolSchemaTokens);
        if (basePromptTokens > prefixBudgetPlan.effectiveMaxTokens() / 2) {
            log.warn("Agent {} 的身份 prompt 约 {} tokens,已超过模型有效窗口 {} 的一半——"
                            + "系统不会截断用户自写的身份 prompt,请自行精简,否则小上下文模型可能无法响应",
                    entity.getId(), basePromptTokens, prefixBudgetPlan.effectiveMaxTokens());
        }

        String enhancedPrompt = buildEnhancedPrompt(entity, builtinSearchEnabled, prefixBudgetPlan.memoryTokens());

        // Runtime skill-catalog renderer — captures this agent's bound skills,
        // effective tool allowlist, model window and workspace; invoked each
        // turn by the reasoning / step-execution nodes with the skills loaded
        // so far this run so load_skill pins float to the top of the catalog.
        SkillCatalogRenderer skillCatalogRenderer = buildSkillCatalogRenderer(
                entity, boundTools, effectiveMaxInputTokens);

        // Progressive tool catalog is shared by both agent types. ReAct applies
        // the split in ReasoningNode; Plan-Execute receives a separate advertised
        // set for StepExecutionNode while its executor retains the full scoped
        // set, so tool_call can recover a deferred tool in the same action round.
        Set<String> autoDemotedTools = Set.of();
        if (prefixBudgetPlan.enabled()) {
            autoDemotedTools = toolDisclosureService.computeAutoDemotions(
                    toolSet, prefixBudgetPlan.toolSchemaBudgetTokens());
        }
        String extensionCatalog = toolDisclosureService.renderExtensionCatalog(
                toolSet, effectiveMaxInputTokens, autoDemotedTools);
        if (extensionCatalog != null && !extensionCatalog.isBlank()) {
            enhancedPrompt = enhancedPrompt + extensionCatalog;
        }

        // 当前仅支持 DashScope 和 OpenAI-compatible，其他协议直接拒绝
        if (!supportsStateGraph(protocol)) {
            throw new MateClawException("err.agent.protocol_not_supported", "当前不支持协议 " + protocol.getId()
                    + "，请切换到 DashScope 或 OpenAI-compatible 模型");
        }

        BaseAgent agent;
        boolean toolCallingEnabled;
        if ("plan_execute".equals(entity.getAgentType())) {
            agent = buildPlanExecuteAgent(toolSet, runtimeModel, maxIter, entity.getId(),
                    skillCatalogRenderer, autoDemotedTools);
            toolCallingEnabled = true;
            log.info("Built StateGraph Plan-Execute agent: {} (maxIterations={}, tools={}, protocol={})",
                    entity.getName(), maxIter, toolSet.size(), protocol.getId());
        } else {
            agent = buildReActAgent(toolSet, runtimeModel, maxIter, entity.getId(), skillCatalogRenderer,
                    prefixBudgetPlan, autoDemotedTools);
            // StateGraph 路径下工具调用由 ActionNode 控制，始终启用
            toolCallingEnabled = true;
            log.info("Built StateGraph ReAct agent: {} (maxIterations={}, tools={}, protocol={})",
                    entity.getName(), maxIter, toolSet.size(), protocol.getId());
        }

        // 设置通用属性
        agent.agentId = String.valueOf(entity.getId());
        agent.agentName = entity.getName();
        agent.systemPrompt = enhancedPrompt;
        agent.maxIterations = maxIter;
        agent.modelName = runtimeModel.getModelName();
        agent.modelCapabilities = modelCapabilityService.resolve(
                runtimeModel.getModelName(), runtimeModel.getModalities());
        agent.runtimeProviderId = provider != null ? provider.getProviderId() : "";
        agent.runtimeModelConfig = runtimeModel;
        agent.toolSet = toolSet;
        // RFC 48 — wire the goal lookup so buildInitialState can inject
        // ACTIVE_GOAL. The node itself stays inert until goalProperties.enabled
        // flips true, but tests need findActiveByConversation to work even
        // when the runtime path is disabled.
        agent.goalService = goalService;
        agent.multimodalRouter = multimodalRouter;
        agent.mediaCaptionService = mediaCaptionService;
        agent.userLocale = resolveLocale();
        agent.temperature = runtimeModel.getTemperature();
        agent.maxTokens = runtimeModel.getMaxTokens();
        agent.maxInputTokens = effectiveMaxInputTokens;
        agent.topP = runtimeModel.getTopP();
        agent.toolCallingEnabled = toolCallingEnabled;

        // Agent-level override takes priority; a relative override is resolved
        // under the workspace basePath so admins can express agent directories
        // relative to the workspace root (matching the UI hint).
        String workspaceBase = null;
        if (entity.getWorkspaceId() != null) {
            try {
                var workspace = workspaceService.getById(entity.getWorkspaceId());
                if (workspace != null) {
                    workspaceBase = workspace.getBasePath();
                }
            } catch (Exception e) {
                log.warn("Failed to lookup workspace basePath for agent {}: {}",
                        entity.getName(), e.getMessage());
            }
        }
        String resolvedBase;
        try {
            resolvedBase = resolveAgentBasePath(entity.getWorkspaceBasePath(), workspaceBase);
        } catch (IllegalArgumentException e) {
            // Override violates the workspace-scoping rule (e.g. admin tried to
            // set an absolute path outside the workspace root). Fall back to
            // inheriting the workspace basePath so chat stays available, but
            // surface the violation in logs so the admin can fix it.
            log.warn("Agent {} workspaceBasePath override rejected, falling back to workspace: {}",
                    entity.getName(), e.getMessage());
            resolvedBase = workspaceBase;
        }
        if (resolvedBase != null && !resolvedBase.isBlank()) {
            agent.workspaceBasePath = resolvedBase;
            boolean fromOverride = entity.getWorkspaceBasePath() != null
                    && !entity.getWorkspaceBasePath().isBlank()
                    && resolvedBase.equals(entity.getWorkspaceBasePath());
            log.info("Agent {} basePath = {} (source: {})",
                    entity.getName(), resolvedBase, fromOverride ? "agent-override" : "workspace");
        }

        log.info("Built agent instance: {} (type={}, protocol={}, tools={}, toolCallingEnabled={})",
                entity.getName(), entity.getAgentType(), protocol.getId(),
                toolSet.size(), agent.toolCallingEnabled);
        return agent;
    }

@Override
    public Flux<AgentService.StreamDelta> chatWithReplayStream(String userMessage, String conversationId,
                                                                String toolCallPayload, String requesterId) {
        setState(AgentState.RUNNING);
        try {
            log.info("[{}] StateGraph chatWithReplayStream: conversationId={}", agentName, conversationId);

            Map<String, Object> inputs = buildInitialState(userMessage, conversationId);
            inputs.put(REQUESTER_ID, requesterId != null ? requesterId : "");
            if (toolCallPayload != null && !toolCallPayload.isEmpty()) {
                inputs.put(FORCED_TOOL_CALL, toolCallPayload);
            }
            String threadId = UUID.randomUUID().toString();
            RunnableConfig config = RunnableConfig.builder().threadId(threadId).build();

            AtomicInteger sentEventCount = new AtomicInteger(0);
            AtomicInteger finalPromptTokens = new AtomicInteger(0);
            AtomicInteger finalCompletionTokens = new AtomicInteger(0);
            AtomicInteger finalCacheReadTokens = new AtomicInteger(0);
            AtomicInteger finalCacheWriteTokens = new AtomicInteger(0);
            AtomicInteger finalReasoningTokens = new AtomicInteger(0);
            AtomicReference<String> finalModelName = new AtomicReference<>("");
            AtomicReference<String> finalProviderId = new AtomicReference<>("");
            // 防重保护：同 chatStructuredStream
            AtomicBoolean finalAnswerEmitted = new AtomicBoolean(false);
            AtomicBoolean finalThinkingEmitted = new AtomicBoolean(false);
            AtomicReference<String> lastEmittedStreamedContent = new AtomicReference<>("");
            AtomicReference<String> lastEmittedIterationThinking = new AtomicReference<>("");
            // Silent-termination guard (mirrors chatStructuredStream)
            AtomicInteger lastIteration = new AtomicInteger(0);
            AtomicInteger lastSoftCap = new AtomicInteger(0);
            AtomicBoolean sawLegitimateExit = new AtomicBoolean(false);

            return BaseAgent.routingStartupDelta(inputs).concatWith(compiledGraph.stream(inputs, config)
                    .flatMapIterable(output -> {
                        List<AgentService.StreamDelta> deltas = new ArrayList<>();
                        List<GraphEventPublisher.GraphEvent> allEvents = GraphEventPublisher.extractEvents(output);
                        int newStart = sentEventCount.get();
                        if (newStart < allEvents.size()) {
                            for (int i = newStart; i < allEvents.size(); i++) {
                                var event = allEvents.get(i);
                                deltas.add(AgentService.StreamDelta.event(event.type(), event.data()));
                            }
                            sentEventCount.set(allEvents.size());
                        }

                        boolean contentAlreadyStreamed = output.state().value(CONTENT_STREAMED, false);
                        boolean thinkingAlreadyStreamed = output.state().value(THINKING_STREAMED, false);

                        // Thinking is emitted BEFORE any content delta of the same
                        // batch. The reasoning that produced an answer precedes the
                        // answer, and the accumulator builds its segment timeline in
                        // delta arrival order — emitting thinking last appended a
                        // thinking segment after the content segment, which readers
                        // then had to reorder. FINAL_THINKING and FINAL_ANSWER are
                        // written by the same node output, so ordering them here is
                        // enough to make the persisted timeline match reality.
                        //
                        // Every iteration's reasoning is persisted, not just the
                        // terminal one. A tool-calling iteration parks its reasoning
                        // in STREAMED_THINKING (REPLACE, one value per node), which
                        // the live channel already broadcast — persistOnly carries it
                        // into the accumulator without a second broadcast. Without
                        // this, a turn that ran N tool rounds kept only the last
                        // round's thinking, so the persisted turn read as a bare
                        // conclusion and the reasoning that justified each tool call
                        // survived nowhere.
                        //
                        // The cursor tracks STREAMED_THINKING and nothing else. A
                        // shared cursor would let the stale value re-qualify: the key
                        // keeps its last write for the rest of the run, so once an
                        // unrelated emission moved a shared cursor past it, the same
                        // span was emitted a second time — after the final answer,
                        // since the later nodes run after the answer was streamed.
                        String iterationThinking = output.state().<String>value(STREAMED_THINKING).orElse("");
                        if (persistEveryIterationReasoning
                                && !iterationThinking.isEmpty()
                                && !iterationThinking.equals(lastEmittedIterationThinking.get())) {
                            lastEmittedIterationThinking.set(iterationThinking);
                            deltas.add(AgentService.StreamDelta.persistOnly(null, iterationThinking));
                        }

                        String thinking = extractFinalThinking(output);
                        if (thinking != null && !thinking.isEmpty()
                                && !thinking.equals(lastEmittedIterationThinking.get())
                                && finalThinkingEmitted.compareAndSet(false, true)) {
                            deltas.add(thinkingAlreadyStreamed
                                    ? AgentService.StreamDelta.persistOnly(null, thinking)
                                    : new AgentService.StreamDelta(null, thinking));
                        }

                        // Route per-iteration STREAMED_CONTENT (reasoning preamble +
                        // SummarizingNode output) into segments only — final-answer
                        // text arrives via the FINAL_ANSWER branch below. Pre-#120
                        // this used persistOnly, which appended every iteration's
                        // narration into the persisted assistant content; next-turn
                        // replay then saw a chain of "Let me try X..." with no
                        // observations and looped retrying tools.
                        //
                        // Exception — evidence-insufficient terminal turn
                        // (ReasoningNode.java:617): when an answer is rejected for
                        // unsupported references, FINAL_ANSWER is replaced with a
                        // short "[证据不足]" warning and STREAMED_CONTENT carries the
                        // actual answer body the user/UI need to see. Falling back
                        // to persistOnly for that case keeps both the original
                        // answer text and the warning in mate_message.content; with
                        // pure segmentOnly the persisted content would shrink to
                        // just the warning, breaking single-segment renderers like
                        // copy / TTS / history reload (segments.length<=1 disables
                        // the segmented view in MessageBubble).
                        boolean isFinalAnswerTurn = hasFinalAnswer(output);
                        String streamed = output.state().<String>value(STREAMED_CONTENT).orElse("");
                        if (!streamed.isEmpty() && !streamed.equals(lastEmittedStreamedContent.get())) {
                            lastEmittedStreamedContent.set(streamed);
                            boolean completionRetry = output.state().value(CONTINUE_REASONING, false);
                            boolean longFormAccumulation = !output.state()
                                    .value(LONG_FORM_DRAFT, "").isEmpty();
                            String resolvedFinalAnswer = isFinalAnswerTurn
                                    ? extractFinalAnswer(output) : "";
                            if (shouldEmitStreamedContent(isFinalAnswerTurn, longFormAccumulation,
                                    streamed, resolvedFinalAnswer)) {
                                addWithKindEvent(deltas, streamedContentDelta(isFinalAnswerTurn,
                                        completionRetry || output.state().value(NEEDS_TOOL_CALL, false),
                                        completionRetry ? 0 : output.state().value(TOOL_CALL_COUNT, 0),
                                        streamed));
                            }
                        }

                        if (isFinalAnswerTurn && finalAnswerEmitted.compareAndSet(false, true)) {
                            String answer = extractFinalAnswer(output);
                            if (answer != null && !answer.isEmpty()) {
                                addWithKindEvent(deltas, AgentService.StreamDelta.finalAnswer(answer, contentAlreadyStreamed));
                            }
                        }

                        finalPromptTokens.set(output.state().value(PROMPT_TOKENS, 0));
                        finalCompletionTokens.set(output.state().value(COMPLETION_TOKENS, 0));
                        finalCacheReadTokens.set(output.state().value(CACHE_READ_TOKENS, 0));
                        finalCacheWriteTokens.set(output.state().value(CACHE_WRITE_TOKENS, 0));
                        finalReasoningTokens.set(output.state().value(REASONING_TOKENS, 0));
                        finalModelName.set(output.state().value(RUNTIME_MODEL_NAME, ""));
                        finalProviderId.set(output.state().value(RUNTIME_PROVIDER_ID, ""));

                        lastIteration.set(output.state().value(CURRENT_ITERATION, 0));
                        lastSoftCap.set(output.state().value(MAX_ITERATIONS, 0));
                        if (hasFinalAnswer(output)
                                || Boolean.TRUE.equals(output.state().value(LIMIT_EXCEEDED, false))
                                || !output.state().<String>value(FINISH_REASON).orElse("").isBlank()) {
                            sawLegitimateExit.set(true);
                        }

                        return deltas;
                    })
                    .concatWith(Mono.fromSupplier(() -> {
                        DelegatedUsageAccumulator acc = DelegatedUsageAccumulator.getInstance();
                        DelegatedUsageAccumulator.Drained delegated = acc != null
                                ? acc.drain(conversationId)
                                : new DelegatedUsageAccumulator.Drained(0, 0);
                        long promptTokens = finalPromptTokens.get() + delegated.promptTokens();
                        long completionTokens = finalCompletionTokens.get() + delegated.completionTokens();
                        if (promptTokens > 0 || completionTokens > 0) {
                            return AgentService.StreamDelta.event("_usage_final", Map.of(
                                    "promptTokens", promptTokens,
                                    "completionTokens", completionTokens,
                                    "delegatedPromptTokens", delegated.promptTokens(),
                                    "delegatedCompletionTokens", delegated.completionTokens(),
                                    "cacheReadTokens", finalCacheReadTokens.get(),
                                    "cacheWriteTokens", finalCacheWriteTokens.get(),
                                    "reasoningTokens", finalReasoningTokens.get(),
                                    "runtimeModelName", finalModelName.get(),
                                    "runtimeProviderId", finalProviderId.get()
                            ));
                        }
                        return null;
                    }).flatMapMany(d -> d != null ? Flux.just(d) : Flux.empty())))
                    .doOnComplete(() -> {
                        setState(AgentState.IDLE);
                        if (!sawLegitimateExit.get()) {
                            log.error("[{}] StateGraph replay stream completed WITHOUT a final answer / "
                                            + "limit_exceeded / finish_reason — likely framework-level silent "
                                            + "termination. conversationId={}, lastIteration={}, softCap={}",
                                    agentName, conversationId, lastIteration.get(), lastSoftCap.get());
                        }
                    })
                    .doOnError(e -> {
                        log.error("[{}] StateGraph replay stream error: {}", agentName, e.getMessage());
                        setState(AgentState.ERROR);
                    })
                    // Leak guard: discard delegated usage if the turn ends without
                    // emitting _usage_final (error / cancel).
                    .doFinally(sig -> {
                        DelegatedUsageAccumulator acc = DelegatedUsageAccumulator.getInstance();
                        if (acc != null) acc.clear(conversationId);
                    });
        } catch (Exception e) {
            setState(AgentState.ERROR);
            return Flux.error(e);
        }
    }

