@Tool(description = """
            Read the contents of a file. Supports line-range reading (1-based). \
            Returns structured JSON with filePath, totalLines, readLines, content. \
            Auto-truncates large files with continuation hints: when the result has \
            truncated=true, continue with the returned nextStartLine (and \
            nextStartColumn when present, to resume reading the rest of a very long \
            line). Text files only; use extract_document_text for PDF/Office documents.""")
    public String read_file(
            @ToolParam(description = "Absolute or relative file path") String filePath,
            @ToolParam(description = "Start line number (1-based, inclusive). Omit to start from line 1", required = false) Integer startLine,
            @ToolParam(description = "End line number (1-based, inclusive). Omit to read to EOF or truncation limit", required = false) Integer endLine,
            @ToolParam(description = "Start character position within startLine (1-based, inclusive). Used to resume reading the rest of a very long line; pass the nextStartColumn from a previous truncated result. Omit to start at the beginning of the line", required = false) Integer startColumn,
            // RFC-063r §2.5: hidden from LLM by JsonSchemaGenerator.
            @Nullable ToolContext ctx) {

        JSONObject result = new JSONObject();
        result.set("filePath", filePath);

        try {
            Path path;
            try {
                // RFC-063r §2.5: forward ToolContext so workspace boundary
                // honors ChatOrigin.workspaceBasePath when available.
                path = vip.mate.tool.guard.WorkspacePathGuard.validatePath(filePath, ctx);
            } catch (IllegalArgumentException e) {
                // Sandbox rejected the literal path. The LLM may have hallucinated
                // a Linux-style path (e.g. /app/Dockerfile) for a chat-upload that
                // actually lives under data/chat-uploads/{conversationId}/. Retry
                // by basename before surfacing the boundary error.
                Path attachment = ChatUploadResolver.resolve(filePath);
                if (attachment == null) {
                    return errorResult(filePath, e.getMessage());
                }
                path = attachment;
            }

            // 文件存在性和类型校验
            if (!Files.exists(path)) {
                // The user-uploaded chat attachment is rendered to the LLM as
                // "[附件] foo.txt" without its stored path, so LLMs often pass
                // just the basename or a guessed absolute path. Fall back to
                // looking up the basename inside the current conversation's
                // chat-upload directory before reporting not-found.
                Path attachment = ChatUploadResolver.resolve(filePath);
                if (attachment == null) {
                    return errorResult(filePath, i18n.msg("tool.read_file.error.not_found", path));
                }
                log.info("[ReadFile] Resolved chat-upload attachment fallback: {} -> {}", filePath, attachment);
                path = attachment;
            }
            if (Files.isDirectory(path)) {
                return errorResult(filePath, i18n.msg("tool.read_file.error.is_directory", path));
            }
            if (!Files.isReadable(path)) {
                return errorResult(filePath, i18n.msg("tool.read_file.error.not_readable", path));
            }

            // 检查是否是二进制文档 - 拒绝直接读取
            String fileName = path.getFileName().toString().toLowerCase();
            for (String ext : DOCUMENT_EXTENSIONS) {
                if (fileName.endsWith(ext)) {
                    return errorResult(filePath, buildDocumentErrorMessage(fileName, ext));
                }
            }

            // 读取所有行
            List<String> allLines = readLinesUtf8(path);
            int totalLines = allLines.size();
            result.set("totalLines", totalLines);

            // 解析行范围
            int start = (startLine != null && startLine > 0) ? startLine : 1;
            int end = (endLine != null && endLine > 0) ? endLine : totalLines;

            // 范围校验
            if (start > totalLines) {
                return errorResult(filePath, i18n.msg("tool.read_file.error.start_exceeds", start, totalLines));
            }
            start = Math.max(1, start);
            end = Math.min(end, totalLines);
            if (start > end) {
                return errorResult(filePath, i18n.msg("tool.read_file.error.start_gt_end", start, end));
            }

            // 提取指定范围的行（转为 0-based）
            List<String> selectedLines = allLines.subList(start - 1, end);

            // Character offset into the FIRST selected line, used to resume reading
            // the tail of a very long line across calls. 1-based on the wire, 0-based
            // here. Only applies to the first line of the selection.
            int firstLineOffset = (startColumn != null && startColumn > 1) ? startColumn - 1 : 0;

            // Truncation control. Each output line carries a "%6d\t" prefix and a
            // trailing newline, so the budget available for a line's own text is the
            // remaining budget minus that overhead.
            StringBuilder sb = new StringBuilder();
            int linesRead = 0;
            boolean truncated = false;
            boolean lineTruncated = false;
            int truncatedLineNum = 0;
            // Where a subsequent read_file call should resume. nextLine is 1-based;
            // nextColumn is a 1-based char offset (1 = start of the line).
            int nextLine = -1;
            int nextColumn = 1;

            for (int i = 0; i < selectedLines.size(); i++) {
                int lineNum = start + i;
                String fullLine = selectedLines.get(i);
                // The offset only applies to the first line of the selection.
                int offset = (i == 0) ? Math.min(firstLineOffset, fullLine.length()) : 0;
                String line = offset > 0 ? fullLine.substring(offset) : fullLine;

                if (linesRead >= DEFAULT_MAX_LINES) {
                    // Hit the line-count cap; resume at this line from the same offset.
                    truncated = true;
                    nextLine = lineNum;
                    nextColumn = offset + 1;
                    break;
                }

                String prefix = String.format("%6d\t", lineNum);
                int lineCost = prefix.length() + line.length() + 1; // +1 for '\n'

                if (sb.length() + lineCost <= MAX_OUTPUT_BYTES) {
                    sb.append(prefix).append(line).append('\n');
                    linesRead++;
                    continue;
                }

                // This line does not fit in the remaining budget.
                boolean fitsAlone = prefix.length() + line.length() + 1 <= MAX_OUTPUT_BYTES;
                if (fitsAlone || linesRead > 0) {
                    // EITHER the line would fit in a fresh budget (normal truncation
                    // at a clean line boundary), OR we have already emitted lines and
                    // defer this oversized line to the next call. Either way, resume
                    // at this line; for non-first lines offset is 0 so column is 1.
                    truncated = true;
                    nextLine = lineNum;
                    nextColumn = offset + 1;
                    break;
                }

                // linesRead == 0 AND the line is larger than the whole budget even on
                // its own. Returning empty content here would yield readLines=0 with a
                // continuation hint that never advances — the infinite retry loop from
                // the original bug. Emit as much of this line as fits (a window),
                // flagged truncated, and advance by exactly the chars consumed so the
                // caller can page through the rest of the line with nextStartColumn.
                String marker = i18n.msg("tool.read_file.line_truncated_marker");
                int windowBudget = MAX_OUTPUT_BYTES - prefix.length() - marker.length() - 1;
                String window = safeTruncate(line, Math.max(0, windowBudget));
                sb.append(prefix).append(window).append(marker).append('\n');
                linesRead++;
                truncated = true;
                lineTruncated = true;
                truncatedLineNum = lineNum;
                int consumed = offset + window.length();
                if (consumed < fullLine.length()) {
                    nextLine = lineNum;       // more of this line remains
                    nextColumn = consumed + 1;
                } else {
                    nextLine = lineNum + 1;   // line exactly consumed; move on
                    nextColumn = 1;
                }
                break;
            }

            result.set("startLine", start);
            result.set("startColumn", firstLineOffset + 1);
            result.set("endLine", start + linesRead - 1);
            result.set("readLines", linesRead);
            result.set("content", sb.toString());

            if (truncated) {
                result.set("truncated", true);
                result.set("nextStartLine", nextLine);
                int kb = MAX_OUTPUT_BYTES / 1024;
                if (lineTruncated && nextColumn > 1) {
                    // A long line was windowed and more of it remains. Surface the
                    // column so the caller can resume reading the same line's tail.
                    result.set("lineTruncated", true);
                    result.set("nextStartColumn", nextColumn);
                    result.set("message", i18n.msg("tool.read_file.line_truncated",
                            truncatedLineNum, kb, nextLine, nextColumn, nextLine + 1));
                } else {
                    if (lineTruncated) {
                        result.set("lineTruncated", true);
                    }
                    result.set("message", i18n.msg("tool.read_file.truncated", DEFAULT_MAX_LINES, kb, nextLine));
                }
            } else {
                result.set("truncated", false);
            }

            log.info("[ReadFile] Read {} lines from {} (lines {}-{})", linesRead, path, start, start + linesRead - 1);

        } catch (Exception e) {
            log.error("[ReadFile] Failed to read file: {}", e.getMessage(), e);
            return errorResult(filePath, i18n.msg("tool.read_file.error.read_exception", e.getMessage()));
        }

        return JSONUtil.toJsonPrettyStr(result);
    }

@Operation(summary = "批准访客会话中的待审批工具调用并重放")
    @PostMapping(value = "/sessions/approve", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public SseEmitter approveSession(
            @RequestHeader("X-MC-Key") String apiKey,
            @RequestHeader(value = "X-MC-Visitor-Token", required = false) String visitorToken,
            @RequestParam String visitorId,
            @RequestParam(required = false) String sessionId,
            @RequestParam String pendingId) {
        SseEmitter emitter = new Utf8SseEmitter(sseTimeoutMillis());
        ChannelEntity channel = resolveChannel(apiKey);
        if (channel == null) {
            sendErrorAndComplete(emitter, "Invalid API Key");
            return emitter;
        }
        if (!verifyVisitorToken(visitorTokenSecret, channel.getId(), visitorId, visitorToken)) {
            sendErrorAndComplete(emitter, "Invalid or missing visitor token");
            return emitter;
        }
        String sid;
        try {
            sid = normalizeSessionId(sessionId);
        } catch (IllegalArgumentException ex) {
            sendErrorAndComplete(emitter, ex.getMessage());
            return emitter;
        }
        String conversationId = deriveConversationId(apiKey, visitorId, sid);
        if (!ownsConversation(conversationId, visitorId)) {
            sendErrorAndComplete(emitter, "Session not found");
            return emitter;
        }
        // IDOR guard (review #415): cross-check the client-supplied pendingId
        // actually belongs to this conversation before resolving, otherwise a
        // visitor could approve + replay another visitor's guarded tool call.
        var ownedApprovalOpt = approvalService.getPending(pendingId);
        if (ownedApprovalOpt.isEmpty()
                || !conversationId.equals(ownedApprovalOpt.get().getConversationId())) {
            sendErrorAndComplete(emitter, "Pending approval not found for this session");
            return emitter;
        }

        AtomicReference<ChatStreamTracker.RunHandle> runHandleRef = new AtomicReference<>();
        AtomicBoolean disconnected = new AtomicBoolean();

        emitter.onCompletion(() -> {
            log.debug("[WebChat] approve SSE completed: {}", conversationId);
            disconnected.set(true);
            streamTracker.detach(runHandleRef.get(), emitter);
        });
        emitter.onTimeout(() -> {
            log.info("[WebChat] approve SSE timeout (stream went idle past the emitter budget): {}", conversationId);
            disconnected.set(true);
            streamTracker.detach(runHandleRef.get(), emitter);
            emitter.complete();
        });
        emitter.onError(e -> {
            if (isClientDisconnect(e)) {
                log.debug("[WebChat] approve SSE client disconnected: {} - {}", conversationId, e.getMessage());
            } else {
                log.info("[WebChat] approve SSE error: {} - {}", conversationId, e.getMessage());
            }
            disconnected.set(true);
            streamTracker.detach(runHandleRef.get(), emitter);
        });

        String actor = webchatUsername(visitorId);
        sseExecutor.execute(() -> {
            // Register + attach the emitter FIRST so every downstream branch
            // (already-resolved, no-agent, error, replay) can broadcast a
            // terminal event the SDK actually receives. Doing this after
            // resolveAndConsume left the already-resolved / error paths
            // broadcasting into a subscriber-less tracker, so the SSE hung
            // to the 10-min timeout (review #415).
            ChatStreamTracker.RunHandle runHandle = streamTracker.register(conversationId);
            runHandleRef.set(runHandle);
            streamTracker.attach(runHandle, emitter);
            if (disconnected.get()) {
                streamTracker.detach(runHandle, emitter);
            }
            try {
                // Atomically consume the approval (DB + metadata + memory, single tx).
                ResolveOutcome consumed = approvalService.resolveAndConsume(pendingId, actor);
                if (consumed.consumedSnapshot() == null) {
                    // already resolved / not found — emit a terminal done so the
                    // SDK's stream listener closes cleanly instead of hanging.
                    broadcastApprovalResolved(runHandle, conversationId, consumed);
                    streamTracker.broadcast(runHandle, "done",
                            "{\"status\":\"already_resolved\"}");
                    streamTracker.closeSubscribers(runHandle);
                    return;
                }

                // Notify the SDK the approval flipped (clears the banner) before
                // replay output starts streaming.
                broadcastApprovalResolved(runHandle, conversationId, consumed);

                PendingApproval snapshot = consumed.consumedSnapshot();
                Long replayAgentId = snapshot.getAgentId() != null
                        ? parseLongOrNull(snapshot.getAgentId()) : null;
                if (replayAgentId == null) {
                    log.warn("[WebChat] approve: no agentId on consumed approval {}, cannot replay",
                            pendingId);
                    streamTracker.broadcast(runHandle, "done",
                            "{\"status\":\"error\",\"message\":\"No agent bound to approval\"}");
                    streamTracker.closeSubscribers(runHandle);
                    return;
                }

                // Restore the original ChatOrigin captured at createPending time.
                // Falls back to a fresh webchat origin when none was persisted
                // (defensive — mirrors ChatController:304-306).
                ChatOrigin replayOrigin =
                        approvalService.restoreChatOrigin(snapshot.getChatOrigin());
                if (replayOrigin == ChatOrigin.EMPTY) {
                    var agent = agentService.getAgent(replayAgentId);
                    Long wsId = agent != null ? agent.getWorkspaceId() : 1L;
                    replayOrigin = ChatOrigin.web(
                            conversationId, actor, wsId, null).withSender(null, "api", null);
                }

                replayOrigin = replayOrigin.withApprovalId(snapshot.getPendingId());

                // Neutral replay prompt (aligned with IM + web channels — naming a
                // tool here can mislead the LLM on fallthrough).
                String replayPrompt = "继续执行已批准的工具调用。";
                StringBuilder assistantReply = new StringBuilder();
                final int[] usage = {0, 0, 0, 0, 0};
                final String[] modelInfo = {null, null};

                streamTracker.broadcast(runHandle, "message_start",
                        "{\"role\":\"assistant\"}");

                Disposable disposable = agentService.chatWithReplayStream(
                        replayAgentId, replayPrompt, conversationId,
                        snapshot.getToolCallPayload(), actor, replayOrigin)
                        .doOnNext(delta -> {
                            if (delta.isEvent() && "_usage_final".equals(delta.eventType())) {
                                Map<String, Object> data = delta.eventData();
                                usage[0] = ((Number) data.getOrDefault("promptTokens", 0)).intValue();
                                usage[1] = ((Number) data.getOrDefault("completionTokens", 0)).intValue();
                                usage[2] = ((Number) data.getOrDefault("cacheReadTokens", 0)).intValue();
                                usage[3] = ((Number) data.getOrDefault("cacheWriteTokens", 0)).intValue();
                                usage[4] = ((Number) data.getOrDefault("reasoningTokens", 0)).intValue();
                                Object model = data.get("runtimeModelName");
                                Object provider = data.get("runtimeProviderId");
                                if (model != null) modelInfo[0] = model.toString();
                                if (provider != null) modelInfo[1] = provider.toString();
                            }
                            if (delta.isEvent()) {
                                forwardVisitorEvent(runHandle, conversationId,
                                        delta.eventType(), delta.eventData());
                            }
                            if (delta.content() != null && !delta.content().isEmpty()) {
                                assistantReply.append(delta.content());
                                if (!delta.persistenceOnly()) {
                                    streamTracker.broadcast(runHandle, "content_delta",
                                            "{\"text\":" + escapeJson(delta.content()) + "}");
                                }
                            }
                            if (delta.thinking() != null && !delta.thinking().isEmpty()
                                    && !delta.persistenceOnly()) {
                                streamTracker.broadcast(runHandle, "thinking_delta",
                                        "{\"text\":" + escapeJson(delta.thinking()) + "}");
                            }
                        })
                        .doOnComplete(() -> {
                            String reply = assistantReply.toString();
                            try {
                                if (!reply.isBlank()) {
                                    conversationService.saveMessage(
                                            conversationId, "assistant", reply, List.of(),
                                            "completed", usage[0], usage[1], usage[2], usage[3], usage[4], modelInfo[0], modelInfo[1], null);
                                }
                            } catch (Exception persistErr) {
                                log.warn("[WebChat] approve replay persist failed: {}", persistErr.getMessage());
                            }
                            streamTracker.broadcast(runHandle, "done",
                                    "{\"status\":\"completed\"}");
                            // Close the WebChat SSE connection on the logical end of
                            // the replay stream — same rationale as /stream (issue #586).
                            streamTracker.closeSubscribers(runHandle);
                            streamTracker.complete(runHandle);
                        })
                        .doOnError(e -> {
                            log.error("[WebChat] approve replay stream error: {}", e.getMessage());
                            streamTracker.broadcast(runHandle, "error",
                                    "{\"message\":" + escapeJson(e.getMessage()) + "}");
                            streamTracker.closeSubscribers(runHandle);
                            streamTracker.complete(runHandle);
                        })
                        .subscribe();
                streamTracker.setDisposable(runHandle, disposable);
                registerEmergencySave(runHandle, conversationId, assistantReply, usage, modelInfo);
            } catch (Exception e) {
                log.error("[WebChat] approve failed for {}: {}", conversationId, e.getMessage());
                try {
                    streamTracker.broadcast(runHandle, "error",
                            "{\"message\":" + escapeJson(e.getMessage()) + "}");
                } catch (Exception ignored) {}
                streamTracker.closeSubscribers(runHandle);
                streamTracker.complete(runHandle);
            }
        });
        audit(channel, visitorId, "webchat.approve-approval", conversationId,
                "{\"pendingId\":\"" + escapeJson(pendingId) + "\",\"replay\":true}");
        return emitter;
    }

public RuntimeSnapshot snapshot(Long workspaceId) {
        List<RunSnapshot> rawRuns = streamTracker.getAllSnapshot();
        Set<Long> agentIds = rawRuns.stream()
                .map(RunSnapshot::agentId)
                .filter(java.util.Objects::nonNull)
                .collect(Collectors.toSet());
        Collection<SubagentRegistry.SubagentRecord> rawSubagents = subagentRegistry.allActive();
        for (var rec : rawSubagents) {
            if (rec.agentId() != null) agentIds.add(rec.agentId());
        }
        Map<Long, AgentEntity> agentInfo = resolveAgents(agentIds);

        Map<String, Long> subagentCountByParent = new HashMap<>();
        for (var rec : rawSubagents) {
            if (!belongsToWorkspace(rec.agentId(), agentInfo, workspaceId)) {
                continue;
            }
            String parent = rec.parentConversationId();
            if (parent != null) {
                subagentCountByParent.merge(parent, 1L, Long::sum);
            }
        }

        List<RunCard> cards = new ArrayList<>(rawRuns.size());
        int stuckCount = 0;
        int orphanCount = 0;
        int queuedTotal = 0;
        int runningCount = 0;
        for (RunSnapshot s : rawRuns) {
            if (s.done()) continue;
            if (!belongsToWorkspace(s.agentId(), agentInfo, workspaceId)) continue;
            runningCount++;
            String stuckReason = computeStuckReason(s);
            boolean orphan = s.subscriberCount() == 0;
            if (stuckReason != null) stuckCount++;
            if (orphan) orphanCount++;
            queuedTotal += s.queueLen();
            int subCount = subagentCountByParent.getOrDefault(s.conversationId(), 0L).intValue();
            AgentEntity ag = s.agentId() == null ? null : agentInfo.get(s.agentId());
            cards.add(new RunCard(
                    s.conversationId(),
                    s.agentId(),
                    ag == null ? null : ag.getName(),
                    ag == null ? null : ag.getIcon(),
                    s.username(),
                    s.currentPhase(),
                    s.runningToolName(),
                    s.waitingReason(),
                    s.done(),
                    s.stopRequested(),
                    s.firstTokenReceived(),
                    s.subscriberCount(),
                    s.queueLen(),
                    s.ageMs(),
                    s.msSinceLastEvent(),
                    stuckReason,
                    orphan,
                    subCount
            ));
        }
        // Sort: stuck first (loudest first), then orphan, then by lastEventAt asc
        cards.sort((a, b) -> {
            int aStuck = a.stuckReason() != null ? 1 : 0;
            int bStuck = b.stuckReason() != null ? 1 : 0;
            if (aStuck != bStuck) return bStuck - aStuck;
            int aOrph = a.orphan() ? 1 : 0;
            int bOrph = b.orphan() ? 1 : 0;
            if (aOrph != bOrph) return bOrph - aOrph;
            return Long.compare(b.msSinceLastEvent(), a.msSinceLastEvent());
        });

        List<SubagentCard> subCards = rawSubagents.stream()
                .filter(rec -> belongsToWorkspace(rec.agentId(), agentInfo, workspaceId))
                .map(rec -> {
                    long now = System.currentTimeMillis();
                    AgentEntity ag = rec.agentId() == null ? null : agentInfo.get(rec.agentId());
                    return new SubagentCard(
                            rec.subagentId(),
                            rec.parentConversationId(),
                            rec.childConversationId(),
                            rec.rootConversationId(),
                            rec.parentSubagentId(),
                            rec.depth(),
                            rec.agentId(),
                            ag == null ? null : ag.getName(),
                            ag == null ? null : ag.getIcon(),
                            rec.goal(),
                            rec.status() != null ? rec.status().get() : null,
                            rec.currentPhase() != null ? rec.currentPhase().get() : null,
                            rec.lastTool() != null ? rec.lastTool().get() : null,
                            rec.toolCount() != null ? rec.toolCount().get() : 0,
                            now - rec.startedAt()
                    );
                })
                .toList();

        Summary summary = new Summary(
                runningCount,
                stuckCount,
                orphanCount,
                queuedTotal,
                subCards.size()
        );

        return new RuntimeSnapshot(summary, cards, subCards, System.currentTimeMillis());
    }

@Tool(description = """
            Delegate a task to another agent asynchronously and return a task_id immediately. \
            Parent continues reasoning while child runs in background. \
            Use task_output(task_id) in a later turn to retrieve the result. \
            Best for long-running sub-tasks (research, file processing) where the parent has \
            other work to do in parallel. For quick tasks where you need the answer immediately, \
            use delegateToAgent instead.""")
    public String delegateAsync(
            @ToolParam(description = "Target Agent name (exact match)") String agentName,
            @ToolParam(description = "Task description with complete context information") String task,
            @ToolParam(description = "Optional short label (≤ 32 chars) for human tracking on the UI badge",
                    required = false) String label,
            @ToolParam(description = "Optional execution budget in seconds. Default 3600, max 86400. Timeout stops the child session and persists a failed task result.",
                    required = false) Integer timeoutSeconds,
            @Nullable ToolContext ctx) {

        if (agentName == null || agentName.isBlank()) {
            return errorJson("agentName 不能为空");
        }
        if (task == null || task.isBlank()) {
            return errorJson("task 不能为空");
        }
        int effectiveTimeoutSeconds;
        try {
            effectiveTimeoutSeconds = resolveAsyncTimeoutSeconds(timeoutSeconds);
        } catch (IllegalArgumentException e) {
            return errorJson(e.getMessage());
        }
        String safeLabel = label == null ? "" :
                (label.length() > ASYNC_LABEL_MAX_CHARS ? label.substring(0, ASYNC_LABEL_MAX_CHARS) : label);

        int depth = DelegationContext.currentDepth();
        if (depth >= MAX_DELEGATION_DEPTH) {
            return errorJson("Delegation depth exceeded (max " + MAX_DELEGATION_DEPTH + ")");
        }

        AgentEntity target = findAgent(agentName);
        if (target == null) {
            return errorJson("Agent not found: " + agentName);
        }

        String parentConversationId = resolveParentConversationId();
        if (parentConversationId == null || parentConversationId.isBlank()) {
            return errorJson("delegateAsync requires a parent conversation context");
        }
        String rootConversationId = DelegationContext.rootConversationId();
        if (rootConversationId == null) rootConversationId = parentConversationId;
        String parentSubagentId = DelegationContext.currentSubagentId();
        int childDepth = depth + 1;
        if (subagentRegistry.isSpawnPaused(parentConversationId)
                || subagentRegistry.isSpawnPaused(rootConversationId)) {
            return errorJson("Spawning paused for this conversation; resume via /api/v1/subagents/spawn-pause");
        }

        // Capture origin / user on the calling thread — the Callable runs on
        // AsyncTaskService.pollExecutor, where the ToolContext ThreadLocal is
        // not visible. The child's identity (agentId) is swapped in below;
        // channel / workspace / requester all propagate via the closure.
        ChatOrigin parentOrigin = ChatOrigin.from(ctx);
        String currentUser = parentOrigin != null && parentOrigin.requesterId() != null
                && !parentOrigin.requesterId().isBlank()
                ? parentOrigin.requesterId()
                : "system";

        String childConversationId = createChildConv(target, parentConversationId);

        // Register first so the subagentId + tree identity can be persisted into
        // the task payload; the registry is process-local, but the request_json
        // is the durable record that task_output authorizes against.
        String subagentId = subagentRegistry.register(parentConversationId, childConversationId,
                target.getId(), task, null, parentSubagentId, childDepth, rootConversationId);
        final String rootConvAsync = rootConversationId;

        String requestJson;
        try {
            Map<String, Object> payload = new LinkedHashMap<>();
            payload.put("parentConversationId", parentConversationId);
            payload.put("rootConversationId", rootConversationId);
            payload.put("childConversationId", childConversationId);
            payload.put("childAgentId", target.getId());
            payload.put("subagentId", subagentId);
            if (parentSubagentId != null) payload.put("parentSubagentId", parentSubagentId);
            payload.put("depth", childDepth);
            payload.put("task", truncate(task, ASYNC_TASK_REQUEST_MAX_CHARS));
            payload.put("label", safeLabel);
            payload.put("timeoutSeconds", effectiveTimeoutSeconds);
            requestJson = objectMapper.writeValueAsString(payload);
        } catch (Exception e) {
            subagentRegistry.unregister(subagentId);
            return errorJson("Failed to serialize task payload: " + e.getMessage());
        }

        AsyncTaskEntity entity;
        try {
            entity = asyncTaskService.submitOneShot(
                    "agent_delegate",
                    parentConversationId,
                    null,
                    requestJson,
                    currentUser,
                    () -> {
                        try {
                            // Detached async child: its usage belongs to the later
                            // task_output retrieval, not the spawning turn, so do not
                            // roll it into the parent's _usage_final.
                            ChildResult childResult = runDetachedChildWithTimeout(
                                    target, task, parentConversationId, childConversationId,
                                    parentOrigin, rootConvAsync, subagentId, childDepth,
                                    effectiveTimeoutSeconds);
                            return childResult.toToolResponse(target.getName());
                        } finally {
                            subagentRegistry.get(subagentId).ifPresent(rec -> {
                                if ("running".equals(rec.status().get())) {
                                    rec.status().set("completed");
                                }
                            });
                            subagentRegistry.unregister(subagentId);
                        }
                    });
        } catch (IllegalStateException e) {
            // Per-user concurrency cap hit inside AsyncTaskService#createTask.
            // Roll back the registry entry so it doesn't dangle.
            subagentRegistry.unregister(subagentId);
            return errorJson(e.getMessage());
        } catch (Exception e) {
            subagentRegistry.unregister(subagentId);
            log.error("delegateAsync submit failed: target={}, err={}", target.getName(), e.getMessage());
            return errorJson("Failed to spawn async task: " + e.getMessage());
        }

        log.info("Async delegation spawned: taskId={}, target={}({}), childConv={}, parentConv={}",
                entity.getTaskId(), target.getName(), target.getId(),
                childConversationId, parentConversationId);

        if (streamTracker.isRunning(rootConvAsync)) {
            Map<String, Object> spawnEvent = delegationPayload(subagentId, parentSubagentId, childDepth,
                    childConversationId, target.getName());
            spawnEvent.put("taskId", entity.getTaskId());
            spawnEvent.put("label", safeLabel);
            spawnEvent.put("task", truncate(task, 200));
            streamTracker.broadcastObject(rootConvAsync, "delegation_async_spawned", spawnEvent);
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("task_id", entity.getTaskId());
        result.put("child_conversation_id", childConversationId);
        result.put("agent_name", target.getName());
        result.put("status", "running");
        result.put("timeout_seconds", effectiveTimeoutSeconds);
        result.put("hint", "Call task_output(task_id) in a later turn to retrieve the result.");
        if (!safeLabel.isEmpty()) {
            result.put("label", safeLabel);
        }
        try {
            return objectMapper.writeValueAsString(result);
